   159→      .post(url)
   160→      .set('Authorization', `Bearer ${tokenFor('ANALYST', 7)}`)
   161→      .send({ oldPassword: 'Str0ng#Pass1' });
   162→    expect(res.status).toBe(400);
   163→    expect(res.body.error).toBe('参数格式不正确');
   164→  });
   165→
   166→  it('新密码强度不达标 → 400（长度/复杂度/含用户名）', async () => {
   167→    querySpy.mockImplementation(dbStub([{ match: 'FROM users WHERE id', rows: [activeUserRow('ANALYST', 7)] }]));
   168→    const auth = `Bearer ${tokenFor('ANALYST', 7)}`;
   169→    for (const weak of ['short1', 'alllowercase', 'u7abc123']) {
   170→      const res = await request(app).post(url).set('Authorization', auth).send({ oldPassword: 'Str0ng#Pass1', newPassword: weak });
   171→      expect(res.status, `弱口令 ${weak} 应被拒绝`).toBe(400);
   172→    }
   173→  });
   174→
   175→  it('原密码不正确 → 400', async () => {
   176→    querySpy.mockImplementation(
   177→      dbStub([
   178→        { match: 'must_change_password FROM users WHERE id', rows: [activeUserRow('ANALYST', 7)] },
   179→        { match: 'SELECT password_hash FROM users', rows: [{ password_hash: hashPassword('Str0ng#Pass1') }] },
   180→      ]),
   181→    );
   182→    const res = await request(app)
   183→      .post(url)
   184→      .set('Authorization', `Bearer ${tokenFor('ANALYST', 7)}`)
   185→      .send({ oldPassword: 'Wrong#Pass9', newPassword: 'N3w#Passw0rd' });
   186→    expect(res.status).toBe(400);
   187→    expect(res.body.error).toBe('原密码不正确');
   188→  });
   189→
   190→  it('新密码与原密码相同 → 400', async () => {
   191→    querySpy.mockImplementation(
   192→      dbStub([
   193→        { match: 'must_change_password FROM users WHERE id', rows: [activeUserRow('ANALYST', 7)] },
   194→        { match: 'SELECT password_hash FROM users', rows: [{ password_hash: hashPassword('Str0ng#Pass1') }] },
   195→      ]),
   196→    );
   197→    const res = await request(app)
   198→      .post(url)
   199→      .set('Authorization', `Bearer ${tokenFor('ANALYST', 7)}`)
   200→      .send({ oldPassword: 'Str0ng#Pass1', newPassword: 'Str0ng#Pass1' });
   201→    expect(res.status).toBe(400);
   202→    expect(res.body.error).toBe('新密码不能与原密码相同');
   203→  });
   204→
   205→  it('改密成功 → 200 且清零 must_change_password', async () => {
   206→    querySpy.mockImplementation(
   207→      dbStub([
   208→        { match: 'must_change_password FROM users WHERE id', rows: [activeUserRow('ANALYST', 7)] },
   209→        { match: 'SELECT password_hash FROM users', rows: [{ password_hash: hashPassword('Str0ng#Pass1') }] },
   210→        { match: 'UPDATE users SET password_hash', rows: [] },
   211→      ]),
   212→    );
   213→    const res = await request(app)
   214→      .post(url)
   215→      .set('Authorization', `Bearer ${tokenFor('ANALYST', 7)}`)
   216→      .send({ oldPassword: 'Str0ng#Pass1', newPassword: 'N3w#Passw0rd' });
   217→    expect(res.status).toBe(200);
   218→    expect(res.body.success).toBe(true);
   219→  });
   220→});
   221→
   222→describe('OIDC 入口：未启用时的契约', () => {
   223→  it('GET /api/auth/oidc/status → 200 且 enabled 为布尔', async () => {
   224→    const res = await request(app).get('/api/auth/oidc/status');
   225→    expect(res.status).toBe(200);
   226→    expect(typeof res.body.enabled).toBe('boolean');
   227→  });
   228→
   229→  it('未启用时 login/callback → 404', async () => {
   230→    const login = await request(app).get('/api/auth/oidc/login');
   231→    expect(login.status).toBe(404);
   232→    expect(login.body.error).toBe('OIDC 未启用');
   233→    const cb = await request(app).get('/api/auth/oidc/callback?code=c&state=s');
   234→    expect(cb.status).toBe(404);
   235→  });
   236→});
