     1→/**
     2→ * P1 高级分析能力路由（挂载于 /api/analytics 前缀下）：
     3→ * - POST /forecast     时序预测（P1-5）：统计引擎出数 + 可选 LLM 业务解读
     4→ * - POST /attribution  多维自动归因（P1-6）：贡献度拆解 + 可选 LLM 结论
     5→ * - POST /whatif       情景推演（P1-9）：基于既有 SQL 的 LLM 改写 → 对比执行 → 解读
     6→ * 预测与归因输入为前端直传的数据（来自图表/看板 widget），纯统计计算零 IO；
     7→ * 推演需要真实数据源执行（复用 executeSafeSql 的表白名单与危险关键字双重校验）。
     8→ */
     9→import { Router } from 'express';
    10→import { authMiddleware, requireRole } from '../auth/auth';
    11→import { checkDataSourceAccess } from '../auth/accessControl';
    12→import { rateLimiter } from '../infra/rateLimiter';
    13→import { writeAudit } from '../infra/auditLog';
    14→import { ERROR_CODES } from '../infra/errorCodes';
    15→import { logger } from '../infra/logger';
    16→import { callLLMJson } from '../llm/llmClient';
    17→import { safeParseJson } from '../../src/utils/queryResultNormalizer';
    18→import { loadSchemaContext, isLiveCapableType } from '../query/schemaContext';
    19→import { executeSafeSql } from '../query/sqlExecutor';
    20→import { forecastSeries, MAX_FORECAST_PERIODS, MIN_SERIES_LENGTH, type ForecastModel } from '../analytics/seriesForecast';
    21→import { attributeDelta, aggregateTwoPeriods, MAX_ATTRIBUTION_ROWS, MAX_ATTRIBUTION_DIMS } from '../analytics/attribution';
    22→import { generateWhatIfPlan, compareOutcomes, summarizeComparison, MAX_SCENARIO_SQL_LENGTH } from '../analytics/whatIf';
    23→
    24→const router = Router();
    25→router.use(authMiddleware);
    26→
    27→const MAX_SERIES_LENGTH = 240;
    28→const WHATIF_ROW_LIMIT = 1000;
    29→const WHATIF_ROWS_RETURN = 50;
    30→
    31→function isPlainObject(v: unknown): v is Record<string, unknown> {
    32→  return !!v && typeof v === 'object' && !Array.isArray(v);
    33→}
    34→
    35→/** LLM 解读兜底：解析失败或调用异常返回 null（不阻断统计结果出数） */
    36→async function tryInterpret(system: string, user: string): Promise<Record<string, unknown> | null> {
    37→  try {
    38→    const text = await callLLMJson(system, user);
    39→    const parsed = safeParseJson(text);
    40→    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed as Record<string, unknown>;
    41→    return null;
    42→  } catch (err: any) {
    43→    logger.warn('[Analytics] LLM 解读失败（降级为仅统计结果）:', err?.message || err);
    44→    return null;
    45→  }
    46→}
    47→
    48→function strList(v: unknown, max: number): string[] | null {
    49→  if (!Array.isArray(v)) return null;
    50→  const out: string[] = [];
    51→  for (const item of v.slice(0, max)) {
    52→    if (item === null || item === undefined) {
    53→      out.push('');
    54→      continue;
    55→    }
    56→    out.push(String(item).slice(0, 200));
    57→  }
    58→  return out;
    59→}
