    62→
    63→const FORECAST_MODELS: ForecastModel[] = ['auto', 'ma', 'lr', 'seasonal'];
    64→
    65→router.post('/forecast', rateLimiter, requireRole('ADMIN', 'ANALYST'), async (req, res) => {
