    69→  if (!Array.isArray(yValuesRaw) || yValuesRaw.length < MIN_SERIES_LENGTH || yValuesRaw.length > MAX_SERIES_LENGTH) {
    70→    return res.status(400).json({ code: ERROR_CODES.INVALID_INPUT, error: `yValues 需为 ${MIN_SERIES_LENGTH}~${MAX_SERIES_LENGTH} 个数值的数组` });
    71→  }
    72→  const yValues = yValuesRaw.map((v: unknown) => Number(v));
    73→  const xValues = strList(body.xValues, MAX_SERIES_LENGTH);
    74→  if (xValues && xValues.length !== yValues.length) {
    75→    return res.status(400).json({ code: ERROR_CODES.INVALID_INPUT, error: 'xValues 与 yValues 长度不一致' });
    76→  }
    77→  const periods = Number.isFinite(Number(body.periods)) ? Math.floor(Number(body.periods)) : 3;
    78→  if (periods < 1 || periods > MAX_FORECAST_PERIODS) {
    79→    return res.status(400).json({ code: ERROR_CODES.INVALID_INPUT, error: `预测期数需为 1~${MAX_FORECAST_PERIODS} 的整数` });
    80→  }
    81→  const model: ForecastModel = FORECAST_MODELS.includes(body.model) ? body.model : 'auto';
    82→  const seasonalPeriod = Number.isFinite(Number(body.seasonalPeriod)) ? Math.floor(Number(body.seasonalPeriod)) : undefined;
    83→  const metricLabel = typeof body.metricLabel === 'string' ? body.metricLabel.trim().slice(0, 60) : '';
    84→  const interpret = body.interpret !== false;
