    90→    return res.status(400).json({ code: ERROR_CODES.INVALID_INPUT, error: err?.message || '预测参数不合法' });
    91→  }
    92→
    93→  let interpretation: Record<string, unknown> | null = null;
    94→  if (interpret) {
    95→    const histTail = yValues.slice(-Math.min(8, yValues.length));
    96→    const system =
    97→      '你是一个数据分析解读助手。根据时序预测的统计结果输出中文业务解读，仅输出 JSON 对象：' +
    98→      '{"summary":"2-3 句总体结论（含方向与幅度）","trendNote":"趋势与节奏判断","riskNote":"不确定性提示（结合预测区间宽度与样本量）"}。' +
    99→      '数值表述与输入一致，不要编造新数字；不要包含 markdown 代码块标记或其他说明文字。';
   100→    const userMsg = [
   101→      `指标：${metricLabel || '未命名指标'}`,
   102→      `历史尾部值（按期序）：${histTail.join(', ')}`,
   103→      `采用模型：${forecast.model}`,
