   135→// ---------------- CRUD ----------------
   136→
   137→export function normalizePatrolInterval(raw: unknown): number | null {
   138→  const n = Number(raw);
   139→  if (!Number.isInteger(n) || n < PATROL_MIN_INTERVAL_MINUTES || n > PATROL_MAX_INTERVAL_MINUTES) return null;
