   142→
   143→export async function listPatrols(dataSourceId?: string, pool?: mysql.Pool): Promise<PatrolPlan[]> {
   144→  const p = pool ?? getPool();
   145→  const hasFilter = typeof dataSourceId === 'string' && dataSourceId.length > 0;
