   147→    ? await p.query<PatrolRow[]>('SELECT * FROM anomaly_patrols WHERE data_source_id = ? ORDER BY id DESC LIMIT 200', [dataSourceId])
   148→    : await p.query<PatrolRow[]>('SELECT * FROM anomaly_patrols ORDER BY id DESC LIMIT 200');
