   152→export async function findPatrol(patrolId: string, pool?: mysql.Pool): Promise<PatrolRow | null> {
   153→  const p = pool ?? getPool();
   154→  const [rows] = await p.query<PatrolRow[]>('SELECT * FROM anomaly_patrols WHERE patrol_id = ? LIMIT 1', [patrolId]);
