   157→
   158→export async function createPatrol(opts: {
   159→  name: string;
   160→  dataSourceId: string;
   161→  intervalMinutes: number;
   162→  user: { id: number; username: string };
   163→  pool?: mysql.Pool;
   164→}): Promise<PatrolPlan> {
   165→  const p = opts.pool ?? getPool();
   166→  const patrolId = `patrol-${randomUUID()}`;
   167→  await p.query(
