   169→     VALUES (?, ?, ?, ?, ?, ?, NOW() + INTERVAL ? MINUTE)`,
   170→    [patrolId, opts.user.id, opts.user.username, opts.dataSourceId, opts.name, opts.intervalMinutes, opts.intervalMinutes],
   171→  );
   172→  const row = await findPatrol(patrolId, p);
   173→  return toPatrolPlan(row as PatrolRow);
