   175→
   176→export async function updatePatrol(
   177→  patrolId: string,
   178→  patch: { name?: string; intervalMinutes?: number; status?: PatrolStatus },
   179→  pool?: mysql.Pool,
   180→): Promise<boolean> {
   181→  const p = pool ?? getPool();
   182→  const sets: string[] = [];
   183→  const args: unknown[] = [];
   184→  if (typeof patch.name === 'string') {
   185→    sets.push('name = ?');
   186→    args.push(patch.name);
   187→  }
   188→  if (patch.intervalMinutes !== undefined) {
   189→    sets.push('interval_minutes = ?');
   190→    args.push(patch.intervalMinutes);
   191→  }
   192→  if (patch.status !== undefined) {
   193→    sets.push('status = ?');
   194→    args.push(patch.status);
   195→    // 恢复启用时重置到期时间（避免停机期间积压的“立即到期”连环补跑）
   196→    if (patch.status === 'ACTIVE') {
   197→      sets.push('next_run_at = NOW() + INTERVAL interval_minutes MINUTE');
   198→    }
   199→  }
   200→  if (sets.length === 0) return false;
   201→  args.push(patrolId);
   202→  const [r] = await p.query<mysql.ResultSetHeader>(`UPDATE anomaly_patrols SET ${sets.join(', ')} WHERE patrol_id = ?`, args);
