   212→
   213→export async function listPatrolRuns(patrolId: string, limit = 20, pool?: mysql.Pool): Promise<PatrolRun[]> {
   214→  const p = pool ?? getPool();
   215→  const [rows] = await p.query<mysql.RowDataPacket[]>(
   216→    'SELECT * FROM anomaly_patrol_runs WHERE patrol_id = ? ORDER BY id DESC LIMIT ?',
   217→    [patrolId, Math.min(100, Math.max(1, limit))],
   218→  );
   219→  return rows.map((row) => {
   220→    let anomalies: AnomalyItem[] = [];
   221→    if (row.anomalies_json) {
   222→      try {
   223→        const parsed = JSON.parse(row.anomalies_json);
   224→        if (Array.isArray(parsed)) anomalies = parsed;
   225→      } catch {
   226→        anomalies = [];
   227→      }
   228→    }
   229→    return {
   230→      id: Number(row.id),
   231→      patrolId: String(row.patrol_id),
   232→      runAt: ts(row.run_at),
   233→      status: (row.status || 'ERROR') as PatrolRunStatus,
   234→      reportId: String(row.report_id || ''),
   235→      reportTitle: String(row.report_title || ''),
   236→      anomalyCount: Number(row.anomaly_count || 0),
   237→      highCount: Number(row.high_count || 0),
   238→      anomalies,
   239→      error: String(row.error || ''),
   240→    };
   241→  });
   242→}
   243→
   244→// ---------------- 扫描执行 ----------------
   245→
   246→/** 取该数据源最近一份 live 决策报表（排除 simulated，避免演示数据触发误报） */
   247→async function loadLatestLiveReport(dataSourceId: string, pool?: mysql.Pool): Promise<{ reportId: string; report: SavedReport } | null> {
   248→  const p = pool ?? getPool();
   249→  const [rows] = await p.query<mysql.RowDataPacket[]>(
   250→    "SELECT report_id, report_data FROM saved_reports WHERE data_source_id = ? AND data_provenance = 'live' ORDER BY created_at DESC LIMIT 1",
   251→    [dataSourceId],
   252→  );
   253→  const row = rows[0];
   254→  if (!row) return null;
   255→  let report: SavedReport;
   256→  try {
   257→    report = JSON.parse(String(row.report_data));
   258→  } catch {
   259→    return null;
   260→  }
   261→  // 结构最小校验：扫描引擎依赖 kpiList 与 charts 数组
   262→  if (!report || !Array.isArray(report.kpiList) || !Array.isArray(report.charts)) return null;
   263→  return { reportId: String(row.report_id), report };
   264→}
   265→
   266→export interface PatrolExecResult {
   267→  status: PatrolRunStatus;
   268→  anomalyCount: number;
   269→  highCount: number;
   270→  reportId: string;
   271→  reportTitle: string;
   272→  anomalies: AnomalyItem[];
   273→  error: string;
   274→}
   275→
   276→/**
   277→ * 执行一次巡检查询并落库（运行历史 + 计划 last_* 快照）。
   278→ * 供调度器与「立即执行」端点共用；扫描引擎为纯统计规则，无 LLM 依赖，秒级完成。
   279→ */
   280→export async function executePatrol(patrolId: string, pool?: mysql.Pool): Promise<PatrolExecResult> {
   281→  const p = pool ?? getPool();
   282→  const plan = await findPatrol(patrolId, p);
   283→  if (!plan) throw new Error('巡检计划不存在');
   284→
   285→  let outcome: PatrolExecResult;
   286→  try {
   287→    const latest = await loadLatestLiveReport(plan.data_source_id, p);
   288→    if (!latest) {
   289→      outcome = { status: 'NO_DATA', anomalyCount: 0, highCount: 0, reportId: '', reportTitle: '', anomalies: [], error: '' };
   290→    } else {
   291→      const scanned = scanReportForAnomalies(latest.report);
   292→      const all = Array.isArray(scanned.anomalies) ? scanned.anomalies : [];
   293→      const sorted = [...all].sort((a, b) => {
   294→        const sev = (x: AnomalyItem) => (x.severity === 'high' ? 2 : x.severity === 'medium' ? 1 : 0);
   295→        return sev(b) - sev(a);
   296→      });
   297→      outcome = {
   298→        status: all.length > 0 ? 'ANOMALY' : 'CLEAN',
   299→        anomalyCount: all.length,
   300→        highCount: all.filter((a) => a.severity === 'high').length,
   301→        reportId: latest.reportId,
   302→        reportTitle: String(latest.report.title || ''),
   303→        anomalies: sorted.slice(0, MAX_STORED_ANOMALIES),
   304→        error: '',
   305→      };
   306→    }
   307→  } catch (err: any) {
   308→    outcome = { status: 'ERROR', anomalyCount: 0, highCount: 0, reportId: '', reportTitle: '', anomalies: [], error: String(err?.message || err).slice(0, 500) };
   309→  }
   310→
   311→  await p.query(
   312→    `INSERT INTO anomaly_patrol_runs (patrol_id, status, report_id, report_title, anomaly_count, high_count, anomalies_json, error)
   313→     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
   314→    [
   315→      patrolId,
   316→      outcome.status,
   317→      outcome.reportId,
   318→      outcome.reportTitle.slice(0, 500),
   319→      outcome.anomalyCount,
   320→      outcome.highCount,
   321→      JSON.stringify(outcome.anomalies),
   322→      outcome.error,
   323→    ],
   324→  );
   325→  await p.query(
   326→    'UPDATE anomaly_patrols SET last_run_at = NOW(), last_run_status = ?, last_anomaly_count = ? WHERE patrol_id = ?',
   327→    [outcome.status, outcome.anomalyCount, patrolId],
   328→  );
   329→  return outcome;
   330→}
   331→
   332→// ---------------- 调度器 ----------------
   333→
   334→let timer: NodeJS.Timeout | null = null;
   335→
   336→/** 调度器 tick 周期（环境变量可覆盖，仅用于测试调快） */
   337→export function patrolSchedulerIntervalMs(): number {
   338→  const n = Number(process.env.PATROL_SCHEDULER_INTERVAL_MS);
   339→  return Number.isFinite(n) && n >= 1000 ? n : 60_000;
   340→}
   341→
   342→/** 单 tick 最多领取的到期计划数 */
   343→export function patrolTickBatch(): number {
   344→  const n = Number(process.env.PATROL_TICK_BATCH);
   345→  return Number.isFinite(n) && n >= 1 ? Math.min(50, Math.floor(n)) : 5;
   346→}
   347→
   348→/**
   349→ * 到期计划原子领取：把 next_run_at 推进到下一周期，affectedRows=1 的实例才执行扫描。
   350→ * 多实例/多 worker 场景下不会重复执行同一计划。
   351→ */
   352→export async function claimDuePatrols(batch = patrolTickBatch(), pool?: mysql.Pool): Promise<PatrolRow[]> {
   353→  const p = pool ?? getPool();
   354→  const [due] = await p.query<PatrolRow[]>(
   355→    "SELECT * FROM anomaly_patrols WHERE status = 'ACTIVE' AND (next_run_at IS NULL OR next_run_at <= NOW()) ORDER BY next_run_at ASC LIMIT ?",
   356→    [batch],
   357→  );
   358→  const claimed: PatrolRow[] = [];
   359→  for (const row of due) {
   360→    const [r] = await p.query<mysql.ResultSetHeader>(
   361→      'UPDATE anomaly_patrols SET next_run_at = NOW() + INTERVAL interval_minutes MINUTE WHERE patrol_id = ? AND status = ? AND (next_run_at IS NULL OR next_run_at <= NOW())',
   362→      [row.patrol_id, 'ACTIVE'],
   363→    );
   364→    if (r.affectedRows === 1) claimed.push(row);
   365→  }
   366→  return claimed;
   367→}
   368→
   369→/** 执行到期计划，返回本轮实际执行的计划数 */
   370→export async function runDuePatrols(pool?: mysql.Pool): Promise<number> {
   371→  const claimed = await claimDuePatrols(patrolTickBatch(), pool);
   372→  for (const row of claimed) {
   373→    try {
   374→      const out = await executePatrol(row.patrol_id, pool);
   375→      logger.info(`[Patrol] ${row.patrol_id} 巡检完成（${out.status}，异常 ${out.anomalyCount} 项）`);
   376→    } catch (err: any) {
   377→      logger.warn(`[Patrol] ${row.patrol_id} 巡检执行失败:`, err?.message || err);
   378→    }
   379→  }
   380→  return claimed.length;
   381→}
   382→
   383→/** 启动调度器（幂等；与 taskQueue 类似内置 worker，不引入外部 cron；tick 级防重入由闭包守卫） */
   384→export function startPatrolScheduler(intervalMs = patrolSchedulerIntervalMs()): void {
   385→  if (timer) return;
   386→  let ticking = false;
   387→  timer = setInterval(() => {
   388→    if (ticking) return; // 上一轮 tick 未完成（慢扫描），跳过本轮避免并发重入
   389→    ticking = true;
   390→    void runDuePatrols()
   391→      .catch((err) => logger.warn('[Patrol] 调度 tick 失败:', err?.message || err))
   392→      .finally(() => {
   393→        ticking = false;
   394→      });
   395→  }, intervalMs);
   396→  timer.unref?.();
   397→  logger.info(`[Patrol] 异常巡检调度器已启动（tick=${intervalMs}ms）`);
   398→}
   399→
   400→/** 测试/停机用 */
   401→export function stopPatrolScheduler(): void {
   402→  if (timer) {
   403→    clearInterval(timer);
   404→    timer = null;
   405→  }
   406→}
   407→

