   230→/**
   231→ * 创建指标。P1-8 治理：ADMIN 创建直接 ACTIVE（version=1）；
   232→ * 非 ADMIN（分析师）创建为提议，status=PENDING，需 ADMIN 审批后才进生产 linking。
   233→ */
   234→export async function createMetric(
   235→  metric: Omit<MetricDefinition, 'id'>,
   236→  createdBy: string,
   237→  opts?: { autoApprove?: boolean }
   238→): Promise<{ ok: true; id: number } | { ok: false; error: string }> {
   239→  const pool = getPool();
   240→  const [dup] = await pool.query<RowDataPacket[]>(
   241→    'SELECT id FROM metric_definitions WHERE data_source_id = ? AND name = ? LIMIT 1',
   242→    [metric.dataSourceId, metric.name]
   243→  );
   244→  if (dup.length > 0) return { ok: false, error: '同名指标已存在' };
   245→  const autoApprove = opts?.autoApprove === true;
   246→  const status: MetricStatus = autoApprove ? metric.status : 'PENDING';
   247→  const [result] = await pool.query<ResultSetHeader>(
   248→    `INSERT INTO metric_definitions (data_source_id, name, aliases_json, description, expr, table_name, filters, dimensions_json, status, version, approved_by, approved_at, created_by)
   249→     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?)`,
   250→    [
   251→      metric.dataSourceId, metric.name, JSON.stringify(metric.aliases), metric.description,
   252→      metric.expr, metric.tableName, metric.filters, JSON.stringify(metric.dimensions || []), status,
   253→      autoApprove ? createdBy : '', autoApprove ? new Date() : null, createdBy,
   254→    ]
   255→  );
   256→  await recordVersion(result.insertId, 1, { ...metric, status }, 'CREATE', createdBy);
   257→  return { ok: true, id: result.insertId };
   258→}
   259→
   260→/** 更新指标（ADMIN）。生效口径变更留历史：version+1 并写快照。仅允许更新非待审批指标。 */
   261→export async function updateMetric(id: number, metric: Omit<MetricDefinition, 'id' | 'dataSourceId'>, actor = ''): Promise<{ ok: true } | { ok: false; error: string; notFound?: boolean }> {
   262→  const pool = getPool();
   263→  const [existing] = await pool.query<RowDataPacket[]>('SELECT * FROM metric_definitions WHERE id = ? LIMIT 1', [id]);
   264→  if (existing.length === 0) return { ok: false, error: '指标不存在', notFound: true };
   265→  const cur = rowToMetric(existing[0]);
   266→  if (cur.status === 'PENDING') return { ok: false, error: '待审批指标请先审批或驳回' };
   267→  const [dup] = await pool.query<RowDataPacket[]>(
   268→    'SELECT id FROM metric_definitions WHERE data_source_id = ? AND name = ? AND id <> ? LIMIT 1',
   269→    [cur.dataSourceId, metric.name, id]
   270→  );
   271→  if (dup.length > 0) return { ok: false, error: '同名指标已存在' };
   272→  const nextVersion = (cur.version || 1) + 1;
   273→  await pool.query(
   274→    `UPDATE metric_definitions SET name = ?, aliases_json = ?, description = ?, expr = ?, table_name = ?, filters = ?, dimensions_json = ?, status = ?, version = ? WHERE id = ?`,
   275→    [metric.name, JSON.stringify(metric.aliases), metric.description, metric.expr, metric.tableName, metric.filters, JSON.stringify(metric.dimensions || []), metric.status, nextVersion, id]
   276→  );
   277→  await recordVersion(id, nextVersion, { ...metric, dataSourceId: cur.dataSourceId }, 'UPDATE', actor);
   278→  return { ok: true };
   279→}
