    24→/** 执行引擎方言：mysql 走 mysql2；postgresql/greenplum 同属 PG 协议走 pg 驱动 */
    25→export type SqlDialect = 'mysql' | 'pg';
    26→
    27→/** 数据源类型 → 执行方言；不支持的类型返回 null */
    28→export function dialectOfDsType(dsType: string): SqlDialect | null {
    29→  if (dsType === 'mysql') return 'mysql';
    30→  if (dsType === 'postgresql' || dsType === 'greenplum') return 'pg';
