   732→ */
   733→/** Prometheus 埋点包装：计时 + 成败 label，真实实现见 executeSafeSqlImpl */
   734→export async function executeSafeSql(
   735→  dataSourceId: string,
   736→  rawSql: unknown,
   737→  allowedTables: { name: string; columns?: { name: string }[] }[],
   738→  sensitiveColumns: string[] = [],
   739→  maxRows: number = MAX_ROWS,
   740→  rowFilters: Record<string, string> = {},
   741→  scenario: QueryScenario = 'interactive'
   742→): Promise<ExecOutcome> {
   743→  const t0 = Date.now();
   744→  try {
   745→    const out = await executeSafeSqlImpl(dataSourceId, rawSql, allowedTables, sensitiveColumns, maxRows, rowFilters, scenario);
   746→    observeSqlExec(Date.now() - t0, out.ok === true);
   747→    return out;
   748→  } catch (err) {
   749→    observeSqlExec(Date.now() - t0, false);
   750→    throw err;
   751→  }
   752→}
   753→
   754→async function executeSafeSqlImpl(
   755→  dataSourceId: string,
   756→  rawSql: unknown,
   757→  allowedTables: { name: string; columns?: { name: string }[] }[],
   758→  sensitiveColumns: string[] = [],
   759→  maxRows: number = MAX_ROWS,
   760→  rowFilters: Record<string, string> = {},
   761→  scenario: QueryScenario = 'interactive'
   762→): Promise<ExecOutcome> {
   763→  const ds = await loadDataSourceConfig(dataSourceId);
   764→  if (!ds) return { ok: false, reason: '数据源不存在' };
   765→  // 文件数据源（v0.9.34：csv/json/excel 上传落应用库 upl_* 物理表）：无独立连接池，
   766→  // 方言按 MySQL 校验（应用库即 MySQL），执行改道应用库
   767→  const fileTable = dialectOfDsType(ds.type) ? null : getFilePhysicalTable(ds.config);
   768→  const dialect = dialectOfDsType(ds.type) || (fileTable ? 'mysql' : null);
   769→  if (!dialect) {
   770→    return { ok: false, reason: 'UNSUPPORTED_DS_TYPE' };
   771→  }
   772→
   773→  const check = validateSelectSql(rawSql, allowedTables, sensitiveColumns, dialect, maxRows);
   774→  if (check.ok !== true) return { ok: false, reason: check.reason };
   775→
   776→  // P1-3 行级权限：校验通过后、执行前强制注入（注入失败 fail-closed）
   777→  const injected = injectRowFilters(check.sql, rowFilters, dialect);
   778→  if (injected.ok !== true) return { ok: false, reason: injected.reason };
   779→  const finalSql = injected.sql;
   780→
   781→  try {
   782→    if (fileTable) {
   783→      // 文件数据源：白名单校验已过（Schema 表名即 upl_* 物理表名，天然隔离越权引用），改在应用库执行。
   784→      // 表为上传快照（导入上限 2 万行），跳过 EXPLAIN 防线（其针对业务库大扫描）；
   785→      // 保留驱动 timeout + MAX_EXECUTION_TIME hint 双保险。
   786→      const timeoutMs = scenarioTimeoutMs(scenario);
   787→      const execSql = injectMysqlMaxExecTime(finalSql, timeoutMs);
   788→      const [fileRows] = await getPool().query({ sql: execSql, timeout: timeoutMs });
   789→      const fileList = (Array.isArray(fileRows) ? fileRows : []) as Record<string, any>[];
   790→      return {
   791→        ok: true,
   792→        result: {
   793→          rows: fileList.slice(0, maxRows),
   794→          rowCount: fileList.length,
   795→          truncated: fileList.length > maxRows,
   796→          finalSql,
   797→          astFallback: check.astFallback === true,
   798→        },
   799→      };
   800→    }
   801→    const entry = getDsPool(dataSourceId, dialect, ds.config, scenario);
   802→    const timeoutMs = scenarioTimeoutMs(scenario);
   803→    // EXPLAIN 防线：真执行前预估扫描量，超阈值拦截（大扫描防拖垮业务库；EXPLAIN 失败 fail-open）
   804→    const guard = await explainGuard(entry, finalSql, scenario);
   805→    if (guard.blocked) return { ok: false, reason: guard.reason, guardBlocked: true };
   806→    let list: Record<string, any>[];
   807→    if (entry.dialect === 'pg') {
   808→      // pg 驱动：超时由建池时的场景化 statement_timeout 承担，结果在 result.rows
   809→      const result = await entry.pool.query(finalSql);
   810→      list = Array.isArray(result.rows) ? result.rows : [];
   811→    } else {
   812→      // MySQL：驱动 query timeout + 服务端 MAX_EXECUTION_TIME hint 双保险（hint 仅注入执行串，
   813→      // 不改变返回给调用方的 finalSql，审计/展示口径保持业务 SQL 原貌）
   814→      const execSql = injectMysqlMaxExecTime(finalSql, timeoutMs);
   815→      const [rows] = await entry.pool.query({ sql: execSql, timeout: timeoutMs });
   816→      list = (Array.isArray(rows) ? rows : []) as Record<string, any>[];
   817→    }
   818→    return {
   819→      ok: true,
   820→      result: {
   821→        rows: list.slice(0, maxRows),
   822→        rowCount: list.length,
   823→        truncated: list.length > maxRows,
   824→        finalSql,
   825→        astFallback: check.astFallback === true,
   826→      },
   827→    };
   828→  } catch (err: any) {
   829→    return { ok: false, reason: `SQL 执行失败：${String(err?.message || err).slice(0, 200)}` };
   830→  }
   831→}
