    33→  total: { current: number; previous: number; delta: number; deltaPct: number | null };
    34→  /** 拉高总指标 TOP N（delta > 0，按 |delta| 降序） */
    35→  topPositive: AttributionItem[];
    36→  /** 拉低总指标 TOP N（delta < 0，按 |delta| 降序） */
    37→  topNegative: AttributionItem[];
    38→  /** 中文诊断（集中度、反向行数、无效分母等） */
    39→  diagnostics: string[];
    40→}
    41→
    42→export const MAX_ATTRIBUTION_ROWS = 200;
    43→export const MAX_ATTRIBUTION_DIMS = 3;
    44→
    45→export function attributeDelta(rows: AttributionInputRow[], opts?: { topN?: number }): AttributionResult {
    46→  if (!Array.isArray(rows) || rows.length === 0) {
    47→    throw new Error('至少需要一行归因数据');
    48→  }
    49→  if (rows.length > MAX_ATTRIBUTION_ROWS) {
    50→    throw new Error(`归因数据行数超出上限（最多 ${MAX_ATTRIBUTION_ROWS} 行）`);
    51→  }
    52→  const topN = Number.isFinite(opts?.topN) && (opts?.topN as number) > 0 ? Math.floor(opts?.topN as number) : 3;
    53→
    54→  let curSum = 0;
    55→  let prevSum = 0;
    56→  const raw = rows.map((r) => {
    57→    const current = Number(r.current);
    58→    const previous = Number(r.previous);
    59→    if (!Number.isFinite(current) || !Number.isFinite(previous)) {
    60→      throw new Error('归因数据包含非数值项');
    61→    }
    62→    curSum += current;
    63→    prevSum += previous;
    64→    return { dims: Array.isArray(r.dims) ? r.dims.map(String) : [], current, previous, delta: current - previous };
    65→  });
    66→
    67→  const absSum = raw.reduce((a, r) => a + Math.abs(r.delta), 0);
    68→
    69→  const items: AttributionItem[] = raw.map((r) => ({
    70→    dims: r.dims,
    71→    current: round4(r.current),
    72→    previous: round4(r.previous),
    73→    delta: round4(r.delta),
    74→    deltaPct: Math.abs(r.previous) > 1e-9 ? round2((r.delta / Math.abs(r.previous)) * 100) : null,
    75→    contribution: absSum > 1e-9 ? round2((r.delta / absSum) * 100) : 0,
    76→    rank: 0,
    77→  }));
    78→
    79→  // 按 |delta| 降序排名
    80→  [...items]
    81→    .sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))
    82→    .forEach((item, idx) => {
    83→      item.rank = idx + 1;
    84→    });
