    86→  const totalDelta = curSum - prevSum;
    87→  const topPositive = items.filter((i) => i.delta > 0).sort((a, b) => b.delta - a.delta).slice(0, topN);
    88→  const topNegative = items.filter((i) => i.delta < 0).sort((a, b) => a.delta - b.delta).slice(0, topN);
    89→
    90→  return {
    91→    items,
    92→    total: {
    93→      current: round4(curSum),
    94→      previous: round4(prevSum),
    95→      delta: round4(totalDelta),
    96→      deltaPct: Math.abs(prevSum) > 1e-9 ? round2((totalDelta / Math.abs(prevSum)) * 100) : null,
    97→    },
    98→    topPositive,
    99→    topNegative,
   100→    diagnostics: describe(items, totalDelta, absSum),
   101→  };
   102→}
   103→
   104→function describe(items: AttributionItem[], totalDelta: number, absSum: number): string[] {
   105→  const out: string[] = [];
   106→  out.push(`共 ${items.length} 个维度组合参与拆解，总体变化 ${totalDelta > 0 ? '+' : ''}${round4(totalDelta)}`);
   107→  if (absSum < 1e-9) {
   108→    out.push('各行变化量绝对值之和为 0（数据无变化），贡献占比不适用');
   109→    return out;
   110→  }
   111→  const reversed = items.filter((i) => totalDelta !== 0 && Math.sign(i.delta) !== 0 && Math.sign(i.delta) !== Math.sign(totalDelta)).length;
   112→  if (reversed > 0) {
   113→    out.push(`存在 ${reversed} 个与总体方向相反的维度组合（整体${totalDelta > 0 ? '上升' : '下降'}中仍${totalDelta > 0 ? '下降' : '上升'}的部分）`);
   114→  }
   115→  const sorted = [...items].sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
   116→  const topAbs = Math.abs(sorted[0].delta);
   117→  const concentration = (topAbs / absSum) * 100;
   118→  if (concentration >= 50) {
   119→    out.push(`变化高度集中：居首维度组合贡献了全部变化量的 ${concentration.toFixed(1)}%，建议优先排查该组合`);
   120→  } else {
   121→    const top3 = sorted.slice(0, 3).reduce((a, b) => a + Math.abs(b.delta), 0);
   122→    out.push(`变化相对分散：前 3 大维度组合合计占全部变化量的 ${((top3 / absSum) * 100).toFixed(1)}%`);
   123→  }
   124→  return out;
   125→}
   126→
   127→function round2(v: number): number {
   128→  return Math.round(v * 100) / 100;
   129→}
   130→
   131→function round4(v: number): number {
   132→  return Math.round(v * 10000) / 10000;
   133→}
   134→
   135→// ---------- 原始数据 → 两期归因行的聚合（路由与 Agent Executor 共用） ----------
   136→
   137→export interface AggregateTwoPeriodsOptions {
   138→  /** 维度列（可空：整表作为单行"合计"） */
   139→  dimKey?: string;
   140→  /** 时期列（必填） */
   141→  periodKey: string;
   142→  /** 指标列（必填，按维度求和） */
   143→  metricKey: string;
   144→}
   145→
   146→export type AggregateTwoPeriodsOutcome =
   147→  | { ok: true; rows: AttributionInputRow[]; periods: [string, string] }
   148→  | { ok: false; reason: string };
   149→
   150→/**
   151→ * 从原始行数据聚合出最新两期的归因输入行：
   152→ * 按时期值（字符串排序）取最新两期，按维度求和当期/对比期指标值。
   153→ */
   154→export function aggregateTwoPeriods(rows: Record<string, unknown>[], opts: AggregateTwoPeriodsOptions): AggregateTwoPeriodsOutcome {
   155→  const { dimKey, periodKey, metricKey } = opts;
   156→  if (!Array.isArray(rows) || rows.length === 0) return { ok: false, reason: '数据为空' };
   157→  if (!periodKey) return { ok: false, reason: '缺少时期列' };
   158→  if (!metricKey) return { ok: false, reason: '缺少指标列' };
   159→
   160→  const allPeriods = Array.from(
   161→    new Set(rows.map((r) => String(r?.[periodKey] ?? '')).filter((v) => v !== '' && v !== 'null' && v !== 'undefined')),
   162→  ).sort((a, b) => a.localeCompare(b, 'zh-CN'));
   163→  if (allPeriods.length < 2) {
   164→    return { ok: false, reason: `时期列仅有 ${allPeriods.length} 期取值（需至少两期）` };
   165→  }
   166→  const [previousPeriod, currentPeriod] = allPeriods.slice(-2);
   167→
   168→  const grouped = new Map<string, { current: number; previous: number }>();
   169→  for (const r of rows) {
   170→    if (!r || typeof r !== 'object') continue;
   171→    const dimVal = dimKey ? String((r as Record<string, unknown>)[dimKey] ?? '') : '合计';
   172→    const periodVal = String((r as Record<string, unknown>)[periodKey]);
   173→    const metricVal = Number((r as Record<string, unknown>)[metricKey]);
   174→    if (!dimVal || !Number.isFinite(metricVal)) continue;
   175→    if (periodVal !== currentPeriod && periodVal !== previousPeriod) continue;
   176→    const entry = grouped.get(dimVal) ?? { current: 0, previous: 0 };
   177→    if (periodVal === currentPeriod) entry.current += metricVal;
   178→    else entry.previous += metricVal;
   179→    grouped.set(dimVal, entry);
   180→  }
   181→  if (grouped.size === 0) return { ok: false, reason: '最新两期无可聚合数据' };
   182→
   183→  return {
   184→    ok: true,
   185→    periods: [previousPeriod, currentPeriod],
   186→    rows: Array.from(grouped.entries()).map(([dim, v]) => ({ dims: [dim], current: v.current, previous: v.previous })),
   187→  };
   188→}
