   103→
   104→/** 指定模型拟合（模型名已解析，非 auto） */
   105→function fitResolved(series: number[], model: ResolvedModel, seasonalPeriod?: number): FittedModel {
   106→  if (model === 'seasonal') {
   107→    const p = Number.isFinite(seasonalPeriod) && (seasonalPeriod as number) >= 2 ? Math.floor(seasonalPeriod as number) : 0;
   108→    if (p < 2 || series.length < 2 * p) {
