   117→/** auto：尾部留出回测按 MAPE 择优；候选不可用/回测无效时降级 */
   118→function pickByBacktest(series: number[]): { chosen: FittedModel; backtest: { model: ResolvedModel; mape: number | null }[] } {
   119→  const n = series.length;
   120→  // 样本过短：回测不可靠，直接用移动平均
   121→  if (n < 8) {
   122→    return { chosen: fitMovingAverage(series), backtest: [] };
   123→  }
   124→  const holdout = Math.min(3, Math.max(2, Math.floor(n * 0.2)));
   125→  const train = series.slice(0, n - holdout);
   126→  const actual = series.slice(n - holdout);
   127→
   128→  const candidates: { model: ResolvedModel; p?: number }[] = [{ model: 'ma' }, { model: 'lr' }];
