   154→// ---------- 模型实现 ----------
   155→
   156→/** 移动平均 + 漂移修正：窗口 min(3, n/2)，外推 = 平滑末端 + 窗口内斜率 × h */
   157→function fitMovingAverage(series: number[]): FittedModel {
