   159→  const w = Math.max(1, Math.min(MA_WINDOW_MAX, Math.floor(n / 2)));
   160→  const smoothed: number[] = [];
   161→  for (let i = 0; i < n; i++) {
   162→    const from = Math.max(0, i - w + 1);
