   177→
   178→/** 最小二乘线性回归 y = a + b·x（x = 1..n） */
   179→function fitLinear(series: number[]): FittedModel {
   180→  const n = series.length;
   181→  const meanX = (n + 1) / 2;
   182→  const meanY = series.reduce((a, b) => a + b, 0) / n;
   183→  let sxy = 0;
   184→  let sxx = 0;
   185→  for (let i = 0; i < n; i++) {
   186→    const dx = i + 1 - meanX;
   187→    sxy += dx * (series[i] - meanY);
   188→    sxx += dx * dx;
   189→  }
   190→  const b = sxx === 0 ? 0 : sxy / sxx;
