   194→    fitted: series.map((_, i) => a + b * (i + 1)),
   195→    predict: (h) => a + b * (n + h),
   196→    slope: b,
   197→  };
   198→}
   199→
   200→/** 加法季节分解：居中移动平均取趋势 → 去趋势求季节增量（按相位归平均、整体均值归零）→ 趋势回归外推 + 季节增量 */
   201→function fitSeasonal(series: number[], p: number): FittedModel {
   202→  const n = series.length;
   203→  const trend: (number | null)[] = new Array(n).fill(null);
   204→  const half = Math.floor(p / 2);
   205→  // 居中移动平均（窗口 p，仅偶数周期精确；奇数周期时会偏半格，作为近似可接受）
   206→  for (let i = half; i < n - half; i++) {
   207→    let sum = 0;
   208→    let cnt = 0;
   209→    for (let j = i - half; j <= i + half; j++) {
   210→      if (j < 0 || j >= n) continue;
   211→      sum += series[j];
   212→      cnt++;
   213→    }
   214→    trend[i] = cnt > 0 ? sum / cnt : null;
   215→  }
   216→  // 季节增量：按相位聚合去趋势偏差
   217→  const seasonalSum = new Array(p).fill(0);
   218→  const seasonalCnt = new Array(p).fill(0);
   219→  for (let i = 0; i < n; i++) {
   220→    if (trend[i] === null) continue;
   221→    const phase = i % p;
   222→    seasonalSum[phase] += series[i] - (trend[i] as number);
   223→    seasonalCnt[phase]++;
   224→  }
   225→  const seasonal = seasonalSum.map((s, i) => (seasonalCnt[i] > 0 ? s / seasonalCnt[i] : 0));
   226→  const seasonMean = seasonal.reduce((a, b) => a + b, 0) / p;
   227→  for (let i = 0; i < p; i++) seasonal[i] -= seasonMean;
   228→  // 趋势：对可得趋势点做线性回归（x 为原始位置 1-based）
   229→  const idx: number[] = [];
   230→  for (let i = 0; i < n; i++) if (trend[i] !== null) idx.push(i);
   231→  const xs = idx.map((i) => i + 1);
   232→  const ys = idx.map((i) => trend[i] as number);
   233→  const { a, b } = ols(xs, ys);
   234→  return {
   235→    name: 'seasonal',
   236→    fitted: series.map((_, i) => a + b * (i + 1) + seasonal[i % p]),
   237→    predict: (h) => a + b * (n + h) + seasonal[(n + h - 1) % p],
   238→    slope: b,
   239→    seasonPeriod: p,
   240→  };
   241→}
   242→
   243→function ols(xs: number[], ys: number[]): { a: number; b: number } {
   244→  const n = xs.length;
   245→  if (n === 0) return { a: 0, b: 0 };
   246→  const meanX = xs.reduce((a, b) => a + b, 0) / n;
   247→  const meanY = ys.reduce((a, b) => a + b, 0) / n;
   248→  let sxy = 0;
   249→  let sxx = 0;
   250→  for (let i = 0; i < n; i++) {
   251→    const dx = xs[i] - meanX;
   252→    sxy += dx * (ys[i] - meanY);
   253→    sxx += dx * dx;
   254→  }
   255→  const b = sxx === 0 ? 0 : sxy / sxx;
   256→  return { a: meanY - b * meanX, b };
   257→}
   258→
   259→// ---------- 评估与诊断 ----------
   260→
   261→/** in-sample 拟合评估：MAPE / RMSE / R² */
   262→export function evaluateFit(series: number[], fitted: number[]): ForecastFit {
   263→  const n = series.length;
   264→  let sse = 0;
   265→  let mapeSum = 0;
