    69→  return Number.isFinite(n) && n >= 0 ? Math.min(3, Math.floor(n)) : 2;
    70→};
    71→/** 每引擎并发上限（默认 4：本地 Ollama 算力有限，超出排队而非打爆推理进程） */
    72→const llmMaxConcurrent = () => {
    73→  const n = Number(process.env.LLM_MAX_CONCURRENT);
    74→  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : 4;
    75→};
    76→/** 熔断：连续失败开路阈值（默认 3）与冷却期（默认 30s，过后半开单探测） */
    77→const breakerFailThreshold = () => {
    78→  const n = Number(process.env.LLM_BREAKER_FAILS);
    79→  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : 3;
    80→};
    81→const breakerCooldownMs = () => {
    82→  const n = Number(process.env.LLM_BREAKER_COOLDOWN_MS);
    83→  return Number.isFinite(n) && n >= 1000 ? Math.floor(n) : 30_000;
    84→};
    85→/** 自适应超时开关（默认开：以近期成功 P95×3 动态收紧配置上限；LLM_ADAPTIVE_TIMEOUT=0 关闭） */
    86→const adaptiveTimeoutEnabled = () => process.env.LLM_ADAPTIVE_TIMEOUT !== '0';
    87→
    88→interface ResilienceState {
    89→  breakers: Record<EngineKind, CircuitBreaker>;
    90→  semaphores: Record<EngineKind, Semaphore>;
    91→  windows: Record<EngineKind, LatencyWindow>;
    92→}
    93→let resilience: ResilienceState | null = null;
    94→/** 未配置主引擎（缺 API Key，如占位 Key 待填期）的故障转移告警去重：仅首次提示避免刷屏 */
    95→const unconfiguredFailoverWarned = new Set<EngineKind>();
    96→function resilienceState(): ResilienceState {
    97→  if (!resilience) {
    98→    resilience = {
    99→      breakers: {
   100→        ollama: new CircuitBreaker({ failureThreshold: breakerFailThreshold(), cooldownMs: breakerCooldownMs() }),
   101→        qwen: new CircuitBreaker({ failureThreshold: breakerFailThreshold(), cooldownMs: breakerCooldownMs() }),
   102→        gemini: new CircuitBreaker({ failureThreshold: breakerFailThreshold(), cooldownMs: breakerCooldownMs() }),
   103→        deepseek: new CircuitBreaker({ failureThreshold: breakerFailThreshold(), cooldownMs: breakerCooldownMs() }),
   104→      },
   105→      semaphores: {
   106→        ollama: new Semaphore(llmMaxConcurrent()),
   107→        qwen: new Semaphore(llmMaxConcurrent()),
   108→        gemini: new Semaphore(llmMaxConcurrent()),
   109→        deepseek: new Semaphore(llmMaxConcurrent()),
   110→      },
   111→      windows: {
   112→        ollama: new LatencyWindow(),
   113→        qwen: new LatencyWindow(),
   114→        gemini: new LatencyWindow(),
   115→        deepseek: new LatencyWindow(),
   116→      },
   117→    };
   118→  }
   119→  return resilience;
   120→}
   121→
   122→/** 测试用：重置全部熔断/信号量/耗时窗口状态 */
   123→export function resetLlmResilienceForTest(): void {
   124→  resilience = null;
   125→  unconfiguredFailoverWarned.clear();
   126→}
   127→
   128→/** 引擎可配置性：ollama 本地默认可试（不可达由熔断接管）；qwen/gemini/deepseek 需密钥 */
   129→function engineConfigured(kind: EngineKind): boolean {
   130→  if (kind === 'ollama') return true;
   131→  if (kind === 'qwen') return Boolean(process.env.QWEN_API_KEY);
   132→  if (kind === 'deepseek') return Boolean(process.env.DEEPSEEK_API_KEY);
   133→  return Boolean(process.env.GEMINI_API_KEY);
   134→}
   135→
   136→/**
   137→ * 引擎级熔断转移：主引擎开路时切换到已配置且未开路的备用引擎
   138→ * （如 Ollama 连续失败自动切 Qwen）；全部开路时 circuitOpen=true，调用方快速失败不雪崩。
   139→ * 主引擎未配置（云端引擎缺 API Key，如占位 Key 待填阶段）时同样直接转移，
   140→ * 避免无效调用与用户可见报错——填 Key 重启后自动切回主引擎。
   141→ */
   142→export function resolveEngineWithFailover(
   143→  primary: EngineKind
   144→): { kind: EngineKind; failovered: boolean; circuitOpen: boolean } {
   145→  const rs = resilienceState();
   146→  if (engineConfigured(primary) && rs.breakers[primary].canRequest()) return { kind: primary, failovered: false, circuitOpen: false };
   147→  const order: EngineKind[] =
   148→    primary === 'ollama'
   149→      ? ['qwen', 'gemini', 'deepseek']
   150→      : primary === 'qwen'
   151→        ? ['ollama', 'gemini', 'deepseek']
   152→        : primary === 'deepseek'
   153→          ? ['ollama', 'qwen', 'gemini']
   154→          : ['qwen', 'ollama', 'deepseek'];
   155→  for (const alt of order) {
   156→    if (engineConfigured(alt) && rs.breakers[alt].canRequest()) {
   157→      if (engineConfigured(primary)) {
   158→        logger.warn(`[LLM] 引擎 ${primary} 熔断开路，本次调用故障转移到 ${alt}`);
   159→      } else if (!unconfiguredFailoverWarned.has(primary)) {
   160→        // 未配置（缺 Key）属稳定状态：仅首次提示，避免每次调用刷屏
   161→        unconfiguredFailoverWarned.add(primary);
   162→        logger.warn(`[LLM] 引擎 ${primary} 未配置（缺 API Key），本次调用转移到 ${alt}；补全 Key 重启后自动切回`);
   163→      }
   164→      return { kind: alt, failovered: true, circuitOpen: false };
   165→    }
   166→  }
   167→  return { kind: primary, failovered: false, circuitOpen: true };
   168→}
   169→
   170→/** 通道调用包装：信号量排队 → 退避重试 → 熔断记账（成功/失败） */
   171→async function callChannel(kind: EngineKind, fn: () => Promise<ChannelOutcome>): Promise<ChannelOutcome> {
   172→  const rs = resilienceState();
   173→  const release = await rs.semaphores[kind].acquire();
   174→  try {
   175→    const outcome = await withRetry(fn, {
   176→      maxRetries: llmRetryMax(),
   177→      onRetry: (err, attempt, delay) =>
   178→        logger.warn(
   179→          `[LLM] ${kind} 调用失败，第 ${attempt} 次重试（${delay}ms 后）：${(err instanceof Error ? err.message : String(err)).slice(0, 120)}`
   180→        ),
   181→    });
   182→    rs.breakers[kind].onSuccess();
   183→    return outcome;
   184→  } catch (err) {
   185→    rs.breakers[kind].onFailure();
   186→    throw err;
   187→  } finally {
   188→    release();
   189→  }
   190→}
   191→
   192→/** 阶段级模型路由（P1-2）：调用方可为单次调用指定引擎/模型（如 SQL 生成用快速小模型） */
   193→export interface LlmStageRoute {
   194→  engine: EngineKind;
   195→  model: string;
   196→}
   197→
   198→/**
   199→ * 阶段级模型路由通用解析：环境变量指定引擎+模型均合法时启用（结构化任务用快速小模型更快更稳）。
   200→ */
   201→function stageRouteFromEnv(engineVar: string, modelVar: string): LlmStageRoute | undefined {
   202→  const engine = String(process.env[engineVar] || '').toLowerCase();
   203→  const model = String(process.env[modelVar] || '').trim();
   204→  if (engine !== 'ollama' && engine !== 'gemini' && engine !== 'qwen' && engine !== 'deepseek') return undefined;
   205→  if (!model || model.length > 100 || !/^[\w.:-]+$/.test(model)) return undefined;
   206→  return { engine: engine as EngineKind, model };
   207→}
   208→
   209→/**
   210→ * SQL 生成阶段的快速模型路由（P1-2）：LLM_SQL_ENGINE + LLM_SQL_MODEL 均配置且合法时启用。
   211→ * 作用于阶段一与复杂度评估（结构化输出任务小模型更快更稳）；阶段二解读默认仍用主模型。
   212→ */
   213→export function sqlStageRoute(): LlmStageRoute | undefined {
   214→  return stageRouteFromEnv('LLM_SQL_ENGINE', 'LLM_SQL_MODEL');
   215→}
   216→
   217→/**
   218→ * 阶段二数据解读的快速模型路由：LLM_ANALYSIS_ENGINE + LLM_ANALYSIS_MODEL 均配置时启用。
   219→ * 解读是问数链路最大耗时项，配置快速模型可大幅提速（质量取舍由部署方决定）。
   220→ */
   221→export function analysisStageRoute(): LlmStageRoute | undefined {
   222→  return stageRouteFromEnv('LLM_ANALYSIS_ENGINE', 'LLM_ANALYSIS_MODEL');
   223→}
   224→
   225→/** 请求级引擎/模型覆盖（用户自选模型）：随异步上下文传递，避免逐层透传参数 */
   226→export interface LlmOverride {
   227→  engine?: EngineKind;
   228→  model?: string;
   229→  /** 请求用户上下文（authMiddleware 注入，随 LLM 用量埋点落库，支撑按用户统计） */
   230→  userId?: number;
   231→  username?: string;
   232→}
   233→const overrideStore = new AsyncLocalStorage<LlmOverride>();
   234→
   235→/** 在当前请求上下文内设置引擎/模型覆盖（合并式 enterWith：保留已注入的用户上下文等字段） */
   236→export function setLlmOverride(override: LlmOverride): void {
   237→  overrideStore.enterWith({ ...overrideStore.getStore(), ...override });
   238→}
   239→
   240→/** 鉴权后注入请求用户上下文（本次请求异步链内的 LLM 用量埋点均携带该用户） */
   241→export function setLlmUserContext(userId: number, username: string): void {
   242→  overrideStore.enterWith({ ...overrideStore.getStore(), userId, username });
   243→}
   244→
   245→/** 当前上下文的用户上下文（无请求上下文时返回空，如启动期/后台任务） */
   246→export function getLlmUserContext(): { userId?: number; username?: string } {
   247→  const o = overrideStore.getStore();
   248→  return o ? { userId: o.userId, username: o.username } : {};
   249→}
   250→
   251→/** 带请求用户上下文的用量埋点：避免逐调用点手动取 store */
   252→export function recordUsage(entry: Parameters<typeof recordLlmUsage>[0]): void {
   253→  const ctx = getLlmUserContext();
   254→  recordLlmUsage({ ...entry, userId: ctx.userId, username: ctx.username });
   255→}
   256→
   257→/** 当前上下文生效的模型名（仅当覆盖引擎与目标通道一致时生效） */
   258→function overrideModel(kind: EngineKind): string | undefined {
   259→  const o = overrideStore.getStore();
   260→  if (!o || !o.model) return undefined;
   261→  return (o.engine || envEngineKind()) === kind ? o.model : undefined;
   262→}
   263→
   264→/** 环境变量级引擎选择（AI_ENGINE 显式 > 密钥存在性） */
   265→function envEngineKind(): EngineKind {
   266→  const explicit = String(process.env.AI_ENGINE || '').toLowerCase();
   267→  if (explicit === 'ollama' || explicit === 'gemini' || explicit === 'qwen' || explicit === 'deepseek') return explicit;
   268→  if (process.env.GEMINI_API_KEY) return 'gemini';
   269→  if (process.env.QWEN_API_KEY) return 'qwen';
   270→  if (process.env.DEEPSEEK_API_KEY) return 'deepseek';
   271→  return 'ollama';
   272→}
   273→
   274→export function engineKind(): EngineKind {
   275→  return overrideStore.getStore()?.engine || envEngineKind();
   276→}
   277→
   278→export function llmEngineLabel(): string {
   279→  const kind = engineKind();
   280→  if (kind === 'gemini') return 'Gemini API';
   281→  if (kind === 'qwen') return `Qwen ${qwenModel()}`;
   282→  if (kind === 'deepseek') return `DeepSeek ${deepseekModel()}`;
   283→  const backends = getOllamaBackendStates();
   284→  return backends.length > 1
   285→    ? `Ollama ${llmModel()} @ ${backends.length} 节点`
   286→    : `Ollama ${llmModel()} @ ${ollamaUrl()}`;
   287→}
   288→
   289→export interface LlmEngineInfo {
   290→  engine: 'ollama' | 'gemini' | 'qwen' | 'deepseek';
   291→  model: string;
   292→  /** 前端展示标签（不含内网地址） */
   293→  label: string;
   294→}
   295→
   296→/** 供前端按实际使用的模型展示提示信息 */
   297→export function llmEngineInfo(): LlmEngineInfo {
   298→  const kind = engineKind();
   299→  if (kind === 'gemini') return { engine: 'gemini', model: geminiModel(), label: `Gemini ${geminiModel()}` };
   300→  if (kind === 'qwen') return { engine: 'qwen', model: qwenModel(), label: `Qwen ${qwenModel()}` };
   301→  if (kind === 'deepseek') return { engine: 'deepseek', model: deepseekModel(), label: `DeepSeek ${deepseekModel()}` };
   302→  return { engine: 'ollama', model: llmModel(), label: `Ollama ${llmModel()}` };
   303→}
   304→
   305→/** 可选模型目录条目（供前端用户自选） */
   306→export interface ModelOption {
   307→  engine: EngineKind;
   308→  model: string;
   309→  label: string;
   310→  /** 是否为服务端默认引擎/模型 */
   311→  isDefault: boolean;
   312→}
   313→
   314→/** 校验用户提交的模型选择；未提供返回 null，非法返回错误原因 */
   315→export function validateModelSelection(
   316→  engine: unknown,
   317→  model: unknown
   318→): { engine: EngineKind; model: string } | { error: string } | null {
   319→  if (engine === undefined || engine === null || engine === '') return null;
   320→  if (typeof engine !== 'string' || !['ollama', 'gemini', 'qwen', 'deepseek'].includes(engine)) {
   321→    return { error: '不支持的模型引擎' };
   322→  }
   323→  if (typeof model !== 'string' || !model.trim() || model.length > 100 || !/^[\w.:-]+$/.test(model)) {
   324→    return { error: '模型名称不合法' };
   325→  }
   326→  return { engine: engine as EngineKind, model: model.trim() };
   327→}
   328→
   329→/**
   330→ * 当前部署可用的模型目录：
   331→ * - ollama：实时拉取 /api/tags 已安装模型（不可达时回退配置项）
   332→ * - qwen/gemini：已配置密钥时列入（模型为环境配置值）
   333→ */
   334→export async function listAvailableModels(): Promise<ModelOption[]> {
   335→  const def = envEngineKind();
   336→  const defModel =
   337→    def === 'qwen'
   338→      ? process.env.QWEN_MODEL || 'qwen3.8-max'
   339→      : def === 'gemini'
   340→        ? GEMINI_MODEL
   341→        : def === 'deepseek'
   342→          ? process.env.DEEPSEEK_MODEL || 'deepseek-flash'
   343→          : process.env.LLM_MODEL || 'deepseek-r1:32b';
   344→  const opts: ModelOption[] = [];
   345→
   346→  // Ollama 本地已安装模型（3s 超时，不可达时仅列配置模型；P2-2 多后端取当前最优节点）
   347→  let ollamaModels: string[] = [];
   348→  try {
   349→    const controller = new AbortController();
   350→    const timer = setTimeout(() => controller.abort(), 3_000);
   351→    const base = pickOllamaBackend()?.url || ollamaUrl();
   352→    const res = await fetch(`${base}/api/tags`, { signal: controller.signal });
   353→    clearTimeout(timer);
   354→    if (res.ok) {
   355→      const json = (await res.json()) as OllamaTagsResponse;
   356→      ollamaModels = Array.isArray(json?.models)
   357→        ? json.models.map((m) => String(m?.name || '')).filter(Boolean)
   358→        : [];
   359→    }
   360→  } catch {
   361→    // Ollama 不可达：仅当其为默认引擎时列出配置模型
   362→  }
   363→  const ollamaList = ollamaModels.length > 0 ? ollamaModels : [process.env.LLM_MODEL || 'deepseek-r1:32b'];
   364→  for (const name of ollamaList) {
   365→    opts.push({ engine: 'ollama', model: name, label: `Ollama ${name}`, isDefault: def === 'ollama' && name === defModel });
   366→  }
   367→
   368→  if (process.env.QWEN_API_KEY) {
   369→    const m = process.env.QWEN_MODEL || 'qwen3.8-max';
   370→    opts.push({ engine: 'qwen', model: m, label: `Qwen ${m}`, isDefault: def === 'qwen' });
   371→  }
   372→  if (process.env.GEMINI_API_KEY) {
   373→    opts.push({ engine: 'gemini', model: GEMINI_MODEL, label: `Gemini ${GEMINI_MODEL}`, isDefault: def === 'gemini' });
   374→  }
   375→  if (process.env.DEEPSEEK_API_KEY) {
   376→    const m = process.env.DEEPSEEK_MODEL || 'deepseek-flash';
   377→    opts.push({ engine: 'deepseek', model: m, label: `DeepSeek ${m}`, isDefault: def === 'deepseek' });
   378→  }
   379→  return opts;
   380→}
   381→
   382→/** 通道层返回：文本 + 可选 token 用量（P2-4 成本埋点，引擎不返回时缺省） */
   383→interface ChannelUsage {
   384→  promptTokens: number;
   385→  completionTokens: number;
   386→}
   387→interface ChannelOutcome {
   388→  text: string;
   389→  usage?: ChannelUsage;
   390→}
   391→
   392→/**
   393→ * OpenAI 兼容 chat 通道（通义千问百炼/Coding Plan、DeepSeek 官方 API 共用）。
   394→ * 端点/密钥/模型/超时按引擎区分：qwen 走 QWEN_URL，deepseek 走 DEEPSEEK_URL。
   395→ */
   396→async function openAiCompatChat(
   397→  engine: 'qwen' | 'deepseek',
   398→  messages: ChatMessage[],
   399→  formatJson = true,
   400→  modelOverride?: string
   401→): Promise<ChannelOutcome> {
   402→  const label = engine === 'qwen' ? 'Qwen' : 'DeepSeek';
   403→  const controller = new AbortController();
   404→  // P0-3 自适应超时：近期成功 P95×3 动态收紧配置上限（慢模型不误杀，快模型不被长超时拖死）
   405→  const configured = engine === 'qwen' ? qwenTimeoutMs() : deepseekTimeoutMs();
   406→  const timeout = adaptiveTimeoutEnabled() ? adaptiveTimeoutMs(resilienceState().windows[engine], configured) : configured;
   407→  const timer = setTimeout(() => controller.abort(), timeout);
   408→
   409→  try {
   410→    const res = await fetch(`${engine === 'qwen' ? qwenUrl() : deepseekUrl()}/chat/completions`, {
   411→      method: 'POST',
   412→      headers: {
   413→        'Content-Type': 'application/json',
   414→        Authorization: `Bearer ${(engine === 'qwen' ? process.env.QWEN_API_KEY : process.env.DEEPSEEK_API_KEY) || ''}`,
   415→      },
   416→      signal: controller.signal,
   417→      body: JSON.stringify({
   418→        model: modelOverride || (engine === 'qwen' ? qwenModel() : deepseekModel()),
   419→        messages,
   420→        stream: false,
   421→        ...(formatJson ? { response_format: { type: 'json_object' } } : {}),
   422→      }),
   423→    });
   424→
   425→    if (!res.ok) {
   426→      const text = await res.text().catch(() => '');
   427→      throw makeLlmError(`${label} API error: ${res.status} ${text}`, { status: res.status });
   428→    }
   429→
   430→    const json = (await res.json()) as OpenAiChatResponse;
   431→    // P2-4 成本埋点：OpenAI 兼容响应带 usage 字段
   432→    const u = json?.usage;
   433→    return {
   434→      text: json.choices?.[0]?.message?.content || '',
   435→      usage: u && (Number(u.prompt_tokens) > 0 || Number(u.completion_tokens) > 0)
   436→        ? { promptTokens: Number(u.prompt_tokens) || 0, completionTokens: Number(u.completion_tokens) || 0 }
   437→        : undefined,
   438→    };
   439→  } catch (err) {
   440→    if (isAbortErr(err)) {
   441→      throw makeLlmError(`${label} 推理超时（超过 ${Math.round(timeout / 1000)} 秒）`, { code: 'TIMEOUT', cause: err });
   442→    }
   443→    throw err;
   444→  } finally {
   445→    clearTimeout(timer);
   446→  }
   447→}
   448→
   449→/** 通义千问 OpenAI 兼容通道（百炼按量 / Coding Plan 均适用，端点由 QWEN_URL 决定） */
   450→const qwenChat = (messages: ChatMessage[], formatJson = true, modelOverride?: string) =>
   451→  openAiCompatChat('qwen', messages, formatJson, modelOverride);
   452→
   453→/** DeepSeek 官方 OpenAI 兼容通道（端点由 DEEPSEEK_URL 决定，默认 https://api.deepseek.com/v1） */
   454→const deepseekChat = (messages: ChatMessage[], formatJson = true, modelOverride?: string) =>
   455→  openAiCompatChat('deepseek', messages, formatJson, modelOverride);
   456→
   457→async function ollamaChat(messages: ChatMessage[], formatJson = true, modelOverride?: string): Promise<ChannelOutcome> {
   458→  const controller = new AbortController();
   459→  const configured = ollamaTimeoutMs();
   460→  const timeout = adaptiveTimeoutEnabled() ? adaptiveTimeoutMs(resilienceState().windows.ollama, configured) : configured;
   461→  const timer = setTimeout(() => controller.abort(), timeout);
   462→
   463→  try {
   464→    // P2-2 多后端：最少并发选取节点，失败自动换次优节点重试
   465→    const res = await withOllamaBackend((base) =>
   466→      fetch(`${base}/api/chat`, {
   467→        method: 'POST',
   468→        headers: { 'Content-Type': 'application/json' },
   469→        signal: controller.signal,
   470→        body: JSON.stringify({
   471→          model: modelOverride || llmModel(),
   472→          messages,
   473→          stream: false,
   474→          // 模型常驻 30 分钟，避免连续问答间卸载/重载开销
   475→          keep_alive: '30m',
   476→          ...(formatJson ? { format: 'json' } : {}),
   477→        }),
   478→      })
   479→    );
   480→
   481→    if (!res.ok) {
   482→      const text = await res.text().catch(() => '');
   483→      throw makeLlmError(`Ollama API error: ${res.status} ${text}`, { status: res.status });
   484→    }
   485→
   486→    const json = (await res.json()) as OllamaChatResponse;
   487→    // P2-4 成本埋点：Ollama 返回 prompt_eval_count / eval_count
   488→    const pt = Number(json?.prompt_eval_count) || 0;
