   164→  // json：数组 of 对象（表头为键并集，按出现顺序）或二维数组（首行为表头）
   165→  const data: unknown = JSON.parse(buf.toString('utf8'));
   166→  if (!Array.isArray(data) || data.length === 0) throw new Error('JSON 文件应为非空数组（对象数组或二维数组）');
   167→  if (Array.isArray(data[0])) {
   168→    const grid = data as unknown[][];
   169→    return capData(grid[0].map((h) => String(h ?? '')), grid.slice(1));
   170→  }
   171→  if (typeof data[0] === 'object' && data[0] !== null) {
   172→    const headers: string[] = [];
   173→    for (const row of data) {
   174→      if (!row || typeof row !== 'object' || Array.isArray(row)) throw new Error('JSON 数组元素类型不一致：应全为对象或全为数组');
   175→      for (const k of Object.keys(row)) if (!headers.includes(k)) headers.push(k);
   176→    }
   177→    const rows = (data as Record<string, unknown>[]).map((r) => headers.map((h) => r[h]));
   178→    return capData(headers, rows);
   179→  }
   180→  throw new Error('JSON 数组元素应为对象或数组');
   181→}
   182→
   183→/** 建物理表并参数化批量写入（先 DROP 同名残留——表名含唯一后缀，正常不会撞车） */
   184→export async function createFileTable(
   185→  physicalTable: string,
   186→  columns: { name: string }[],
   187→  types: ('DOUBLE' | 'TEXT')[],
   188→  rows: unknown[][]
   189→): Promise<void> {
   190→  if (!PHYSICAL_TABLE_RE.test(physicalTable)) throw new Error('非法物理表名');
   191→  const pool = getPool();
   192→  const colDefs = columns.map((c, i) => `\`${c.name}\` ${types[i]} NULL`).join(', ');
   193→  await pool.query(`DROP TABLE IF EXISTS \`${physicalTable}\``);
   194→  await pool.query(`CREATE TABLE \`${physicalTable}\` (${colDefs}) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);
   195→  const colList = columns.map((c) => `\`${c.name}\``).join(', ');
   196→  for (let i = 0; i < rows.length; i += INSERT_BATCH) {
   197→    const batch = rows.slice(i, i + INSERT_BATCH);
   198→    const values = batch.map((r) => columns.map((_, ci) => toCellValue(r[ci], types[ci])));
   199→    await pool.query(`INSERT INTO \`${physicalTable}\` (${colList}) VALUES ?`, [values]);
   200→  }
   201→}
   202→
   203→/** 级联删除物理表（仅 upl_ 前缀白名单；删除失败由调用方决定告警或阻断） */
   204→export async function dropFileTable(physicalTable: string): Promise<void> {
   205→  if (!PHYSICAL_TABLE_RE.test(physicalTable)) throw new Error('非法物理表名');
   206→  await getPool().query(`DROP TABLE IF EXISTS \`${physicalTable}\``);
   207→}
