     1→/**
     2→ * v0.9.20 报表生成效率优化单测（对照问数链路效率方案）：
     3→ * ① 执行阶段并行化——多条查询计划 Promise.all 并发过安全执行层（墙钟=最慢一条，而非逐条相加），
     4→ *    部分失败跳过、汇总保持计划原顺序（executedSqls 与 charts 索引对齐，下钻依赖）；
     5→ * ② 阶段二接入 analysisStageRoute 快速模型路由（LLM_ANALYSIS_* 配置时生效，未配置回退主模型）。
     6→ */
     7→import { describe, expect, it, vi, beforeEach } from 'vitest';
     8→import { runLiveReport, type ReportQueryPlan } from './liveReport';
     9→import { callLLMJson } from '../llm/llmClient';
    10→import { executeSafeSql } from '../query/sqlExecutor';
    11→
    12→vi.mock('../llm/llmClient', () => ({
    13→  callLLMJson: vi.fn(),
    14→  analysisStageRoute: vi.fn(() => ({ engine: 'ollama', model: 'qwen3:8b' })),
    15→  sqlStageRoute: vi.fn(() => undefined),
    16→}));
    17→vi.mock('../query/sqlExecutor', () => ({ executeSafeSql: vi.fn() }));
    18→vi.mock('../query/metrics', () => ({
    19→  loadActiveMetrics: vi.fn().mockResolvedValue([]),
    20→  matchMetrics: vi.fn().mockReturnValue([]),
    21→  buildMetricPrompt: vi.fn().mockReturnValue(''),
    22→}));
    23→vi.mock('../query/ironRules', () => ({
    24→  loadActiveIronRules: vi.fn().mockResolvedValue([]),
    25→  buildIronRulesPrompt: vi.fn().mockReturnValue(''),
    26→}));
    27→vi.mock('../knowledge/knowledgeBase', () => ({ retrieveKnowledgeSnippets: vi.fn().mockResolvedValue('') }));
    28→
    29→const mockedLLM = vi.mocked(callLLMJson);
    30→const mockedExec = vi.mocked(executeSafeSql);
    31→
    32→const STAGE2_JSON = JSON.stringify({
    33→  title: '测试报表',
    34→  summary: '摘要',
    35→  insights: [],
    36→  kpiList: [],
    37→  commentaries: ['c1', 'c2', 'c3'],
    38→});
    39→
    40→function makePlans(n: number): { reportTitle: string; plans: ReportQueryPlan[] } {
    41→  return {
    42→    reportTitle: '测试报表',
    43→    plans: Array.from({ length: n }, (_, i) => ({
    44→      title: `图${i}`,
    45→      sql: `SELECT dim, SUM(val) AS val FROM t1 /*p${i}*/ GROUP BY dim`,
    46→      chartType: 'bar',
    47→      xAxisKey: 'dim',
    48→      yAxisKeys: ['val'],
    49→      columnNames: { dim: '维度', val: '数值' },
    50→      purpose: `用途${i}`,
    51→    })),
    52→  };
    53→}
    54→
    55→const BASE_INPUT = {
    56→  templateType: '综合经营分析',
    57→  customPrompt: '',
    58→  schema: [
    59→    {
    60→      name: 't1',
    61→      displayName: '测试表',
    62→      columns: [
    63→        ['dim', 'varchar', '维度'],
    64→        ['val', 'decimal', '数值'],
    65→      ],
    66→    },
    67→  ] as any[],
    68→  guidance: '',
    69→  dataSourceId: 'ds_perf',
    70→  sensitiveRemoved: [] as string[],
    71→};
    72→
    73→/** 从 SQL 注释中提取计划序号（/*pN*\/） */
    74→function planIdxOf(sql: unknown): number {
    75→  const m = /\/\*p(\d+)\*\//.exec(String(sql));
    76→  return m ? Number(m[1]) : -1;
    77→}
    78→
    79→beforeEach(() => {
    80→  vi.clearAllMocks();
    81→  mockedLLM.mockResolvedValue(STAGE2_JSON);
    82→});
    83→
    84→describe('报表执行阶段并行化（v0.9.20）', () => {
    85→  it('多条查询计划并发执行（最大在飞数=计划数），汇总保持计划原顺序', async () => {
    86→    let inflight = 0;
    87→    let maxInflight = 0;
    88→    mockedExec.mockImplementation(async (_ds, sql) => {
    89→      const idx = planIdxOf(sql);
    90→      inflight++;
    91→      maxInflight = Math.max(maxInflight, inflight);
    92→      // 序号越大返回越快（完成顺序与计划顺序相反），验证汇总顺序不依赖完成顺序
    93→      await new Promise((r) => setTimeout(r, 60 - idx * 20));
    94→      inflight--;
    95→      return { ok: true, result: { rows: [{ dim: `d${idx}`, val: idx + 1 }], finalSql: String(sql), rowCount: 1 } } as any;
    96→    });
    97→
    98→    const approvedPlans = makePlans(3);
    99→    const out = await runLiveReport({ ...BASE_INPUT, approvedPlans });
   100→
   101→    expect(out.ok).toBe(true);
   102→    expect(maxInflight).toBe(3); // 3 条计划真实并发（串行实现 maxInflight 恒为 1）
   103→    if (out.ok) {
   104→      // executedSqls 与 charts 严格按计划顺序（p0/p1/p2），不受完成顺序（p2 先回）影响
   105→      expect(out.executedSqls.map((s) => planIdxOf(s))).toEqual([0, 1, 2]);
   106→      expect(out.report.charts.map((c: any) => c.data[0].dim)).toEqual(['d0', 'd1', 'd2']);
   107→      expect(out.totalRows).toBe(3);
   108→    }
   109→  });
   110→
   111→  it('部分查询失败跳过，其余正常生成（executedSqls 与 charts 仍对齐）', async () => {
   112→    mockedExec.mockImplementation(async (_ds, sql) => {
   113→      const idx = planIdxOf(sql);
   114→      if (idx === 1) return { ok: false, reason: '模拟执行失败' } as any;
