   296→      });
   297→      outcome = {
   298→        status: all.length > 0 ? 'ANOMALY' : 'CLEAN',
   299→        anomalyCount: all.length,
   300→        highCount: all.filter((a) => a.severity === 'high').length,
   301→        reportId: latest.reportId,
   302→        reportTitle: String(latest.report.title || ''),
   303→        anomalies: sorted.slice(0, MAX_STORED_ANOMALIES),
   304→        error: '',
   305→      };
   306→    }
   307→  } catch (err: any) {
   308→    outcome = { status: 'ERROR', anomalyCount: 0, highCount: 0, reportId: '', reportTitle: '', anomalies: [], error: String(err?.message || err).slice(0, 500) };
   309→  }
   310→
   311→  await p.query(
   312→    `INSERT INTO anomaly_patrol_runs (patrol_id, status, report_id, report_title, anomaly_count, high_count, anomalies_json, error)
   313→     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
   314→    [
   315→      patrolId,
   316→      outcome.status,
   317→      outcome.reportId,
   318→      outcome.reportTitle.slice(0, 500),
   319→      outcome.anomalyCount,
   320→      outcome.highCount,
   321→      JSON.stringify(outcome.anomalies),
   322→      outcome.error,
   323→    ],
   324→  );
   325→  await p.query(
   326→    'UPDATE anomaly_patrols SET last_run_at = NOW(), last_run_status = ?, last_anomaly_count = ? WHERE patrol_id = ?',
   327→    [outcome.status, outcome.anomalyCount, patrolId],
   328→  );
   329→  return outcome;
   330→}
   331→
   332→// ---------------- 调度器 ----------------
   333→
   334→let timer: NodeJS.Timeout | null = null;
   335→
   336→/** 调度器 tick 周期（环境变量可覆盖，仅用于测试调快） */
   337→export function patrolSchedulerIntervalMs(): number {
   338→  const n = Number(process.env.PATROL_SCHEDULER_INTERVAL_MS);
   339→  return Number.isFinite(n) && n >= 1000 ? n : 60_000;
   340→}
   341→
   342→/** 单 tick 最多领取的到期计划数 */
   343→export function patrolTickBatch(): number {
   344→  const n = Number(process.env.PATROL_TICK_BATCH);
   345→  return Number.isFinite(n) && n >= 1 ? Math.min(50, Math.floor(n)) : 5;
   346→}
   347→
   348→/**
   349→ * 到期计划原子领取：把 next_run_at 推进到下一周期，affectedRows=1 的实例才执行扫描。
   350→ * 多实例/多 worker 场景下不会重复执行同一计划。
   351→ */
   352→export async function claimDuePatrols(batch = patrolTickBatch(), pool?: mysql.Pool): Promise<PatrolRow[]> {
   353→  const p = pool ?? getPool();
   354→  const [due] = await p.query<PatrolRow[]>(
   355→    "SELECT * FROM anomaly_patrols WHERE status = 'ACTIVE' AND (next_run_at IS NULL OR next_run_at <= NOW()) ORDER BY next_run_at ASC LIMIT ?",
   356→    [batch],
   357→  );
   358→  const claimed: PatrolRow[] = [];
   359→  for (const row of due) {
   360→    const [r] = await p.query<mysql.ResultSetHeader>(
   361→      'UPDATE anomaly_patrols SET next_run_at = NOW() + INTERVAL interval_minutes MINUTE WHERE patrol_id = ? AND status = ? AND (next_run_at IS NULL OR next_run_at <= NOW())',
   362→      [row.patrol_id, 'ACTIVE'],
   363→    );
   364→    if (r.affectedRows === 1) claimed.push(row);
   365→  }
   366→  return claimed;
   367→}
   368→
   369→/** 执行到期计划，返回本轮实际执行的计划数 */
   370→export async function runDuePatrols(pool?: mysql.Pool): Promise<number> {
   371→  const claimed = await claimDuePatrols(patrolTickBatch(), pool);
   372→  for (const row of claimed) {
   373→    try {
   374→      const out = await executePatrol(row.patrol_id, pool);
   375→      logger.info(`[Patrol] ${row.patrol_id} 巡检完成（${out.status}，异常 ${out.anomalyCount} 项）`);
   376→    } catch (err: any) {
   377→      logger.warn(`[Patrol] ${row.patrol_id} 巡检执行失败:`, err?.message || err);
   378→    }
   379→  }
   380→  return claimed.length;
   381→}
   382→
   383→/** 启动调度器（幂等；与 taskQueue 类似内置 worker，不引入外部 cron；tick 级防重入由闭包守卫） */
   384→export function startPatrolScheduler(intervalMs = patrolSchedulerIntervalMs()): void {
   385→  if (timer) return;
   386→  let ticking = false;
   387→  timer = setInterval(() => {
   388→    if (ticking) return; // 上一轮 tick 未完成（慢扫描），跳过本轮避免并发重入
   389→    ticking = true;
   390→    void runDuePatrols()
   391→      .catch((err) => logger.warn('[Patrol] 调度 tick 失败:', err?.message || err))
   392→      .finally(() => {
   393→        ticking = false;
   394→      });
   395→  }, intervalMs);
   396→  timer.unref?.();
   397→  logger.info(`[Patrol] 异常巡检调度器已启动（tick=${intervalMs}ms）`);
   398→}
   399→
   400→/** 测试/停机用 */
   401→export function stopPatrolScheduler(): void {
   402→  if (timer) {
   403→    clearInterval(timer);
   404→    timer = null;
   405→  }
   406→}
   407→

