     1→/**
     2→ * P1-1 语义指标层：管理员登记结构化业务指标定义（名称/同义词/聚合口径/归属表/固定过滤），
     3→ * 问数阶段一按「问题命中指标名/同义词 → 模板化注入口径」生成 SQL，
     4→ * 保证同一指标全系统口径一致，消除 LLM 每次自由发挥导致的指标漂移。
     5→ * 指标文本仅注入 prompt（不直接拼接 SQL），生成结果仍过安全执行层校验。
     6→ *
     7→ * P1-8 指标层治理：提议（PENDING，分析师可发起）→ ADMIN 审批（ACTIVE/REJECTED）→ 生效版本化。
     8→ * 未审批（PENDING/REJECTED）指标不进生产 linking（loadActiveMetrics 仅取 ACTIVE）；
     9→ * 每次创建/审批/变更/回滚均写 metric_versions 快照，变更留历史、可回溯。
    10→ *
    11→ * P2-14 语义层独立资产（对齐 dbt Semantic Layer 思路）：指标定义升级为
    12→ * 「聚合口径 expr + 归属表 + 固定过滤 + 可切分维度 dimensions」的完整语义资产，
    13→ * 并提供统一指标查询端点（POST /api/metrics/query：按白名单维度生成 GROUP BY 查询并执行），
    14→ * 供问数（prompt 注入）/报表（口径注入）/看板（指标卡直查）三端共享同一权威口径。
    15→ */
    16→import type { RowDataPacket, ResultSetHeader } from 'mysql2';
    17→import { getPool } from '../infra/db';
    18→
    19→/** P1-8 治理状态机：PENDING 待审批 → ACTIVE 生效 / REJECTED 驳回；DISABLED 停用 */
    20→export type MetricStatus = 'PENDING' | 'ACTIVE' | 'REJECTED' | 'DISABLED';
    21→
    22→export interface MetricDefinition {
    23→  id?: number;
    24→  dataSourceId: string;
    25→  /** 指标名（数据源内唯一），如「有效客户数」 */
    26→  name: string;
    27→  /** 同义词列表，参与问数命中匹配 */
    28→  aliases: string[];
    29→  /** 口径说明（面向人的解释） */
    30→  description: string;
    31→  /** 聚合表达式，如 COUNT(DISTINCT id) / SUM(amount) */
    32→  expr: string;
    33→  /** 归属表名（须与 Schema 表名一致） */
    34→  tableName: string;
    35→  /** 固定过滤条件（WHERE 片段，可为空），如 status = 'active' */
    36→  filters: string;
    37→  /** P2-14 可切分维度白名单（归属表的列名）：统一指标查询允许按这些列 GROUP BY */
    38→  dimensions: string[];
    39→  status: MetricStatus;
    40→  /** 生效版本号（每次审批生效/变更/回滚递增） */
    41→  version?: number;
    42→  approvedBy?: string;
    43→  approvedAt?: string | null;
    44→  createdBy?: string;
    45→}
    46→
    47→const MAX_METRICS_PER_DS = 200;
    48→
    49→/** 校验并规整指标输入；非法时返回 error 说明（路由层据此 400） */
    50→export function sanitizeMetricInput(input: any): { ok: true; metric: Omit<MetricDefinition, 'id'> } | { ok: false; error: string } {
    51→  const dataSourceId = typeof input?.dataSourceId === 'string' ? input.dataSourceId.trim() : '';
    52→  const name = typeof input?.name === 'string' ? input.name.trim() : '';
    53→  const expr = typeof input?.expr === 'string' ? input.expr.trim() : '';
    54→  const tableName = typeof input?.tableName === 'string' ? input.tableName.trim() : '';
    55→  const filters = typeof input?.filters === 'string' ? input.filters.trim() : '';
    56→  // P2-14 维度白名单：仅接受合法标识符（防注入），去重，上限 10 个
    57→  const dimensions = Array.isArray(input?.dimensions)
    58→    ? [...new Set(input.dimensions.filter((d: any) => typeof d === 'string').map((d: string) => d.trim()).filter(Boolean))] as string[]
    59→    : [];
    60→  const description = typeof input?.description === 'string' ? input.description.trim().slice(0, 300) : '';
    61→  const aliases = Array.isArray(input?.aliases)
    62→    ? input.aliases.filter((a: any) => typeof a === 'string' && a.trim()).map((a: string) => a.trim().slice(0, 50)).slice(0, 10)
    63→    : [];
    64→
    65→  if (!dataSourceId) return { ok: false, error: '缺少 dataSourceId' };
    66→  if (!name || name.length > 50) return { ok: false, error: '指标名必填且不超过 50 字' };
    67→  if (!expr || expr.length > 200) return { ok: false, error: '聚合表达式必填且不超过 200 字' };
    68→  if (/;\s*\S/.test(expr) || /;\s*\S/.test(filters)) return { ok: false, error: '表达式/过滤条件不允许多语句' };
    69→  if (!/^[A-Za-z_][\w]*$/.test(tableName)) return { ok: false, error: '归属表名必须是合法标识符' };
    70→  if (filters.length > 300) return { ok: false, error: '固定过滤条件不超过 300 字' };
    71→  if (aliases.some((a: string) => a === name)) return { ok: false, error: '同义词不能与指标名相同' };
    72→  if (dimensions.length > 10) return { ok: false, error: '可切分维度不超过 10 个' };
    73→  if (dimensions.some((d) => !/^[A-Za-z_][\w]*$/.test(d))) return { ok: false, error: '维度列名必须是合法标识符' };
    74→  if (dimensions.some((d) => d.toLowerCase() === tableName.toLowerCase())) return { ok: false, error: '维度不能与归属表同名' };
    75→
    76→  return {
    77→    ok: true,
    78→    // status 输入仅接受 ACTIVE/DISABLED；PENDING/REJECTED 由治理流程驱动，不接受外部直填
    79→    metric: { dataSourceId, name, aliases, description, expr, tableName, filters, dimensions, status: input?.status === 'DISABLED' ? 'DISABLED' : 'ACTIVE' },
    80→  };
    81→}
    82→
    83→function normalizeStatus(raw: any): MetricStatus {
    84→  return raw === 'PENDING' || raw === 'REJECTED' || raw === 'DISABLED' ? raw : 'ACTIVE';
    85→}
    86→
    87→/** 问题命中匹配：指标名或任一同义词作为子串出现在问题中即命中（确定性、零延迟） */
    88→export function matchMetrics(query: string, metrics: MetricDefinition[]): MetricDefinition[] {
    89→  const q = String(query || '');
    90→  if (!q.trim()) return [];
    91→  return metrics.filter((m) => {
    92→    if (q.includes(m.name)) return true;
    93→    return m.aliases.some((a) => a && q.includes(a));
    94→  });
    95→}
    96→
    97→/** 命中指标的模板化 prompt 段：逐条给出口径，强制阶段一遵循；P2-14 列出可切分维度 */
    98→export function buildMetricPrompt(hits: MetricDefinition[]): string {
    99→  if (hits.length === 0) return '';
   100→  const lines = hits.map((m) => {
   101→    const filter = m.filters ? `，固定过滤条件：WHERE ${m.filters}` : '';
   102→    const alias = m.aliases.length > 0 ? `（同义词：${m.aliases.join('、')}）` : '';
   103→    const desc = m.description ? `，口径说明：${m.description}` : '';
   104→    const dims = m.dimensions.length > 0 ? `，可切分维度：${m.dimensions.join('、')}` : '';
   105→    return `- ${m.name}${alias} = ${m.expr}，基于表 ${m.tableName}${filter}${dims}${desc}`;
   106→  });
   107→  return `【语义指标层定义】（管理员登记的权威口径，问题涉及以下指标时必须严格使用给定的聚合表达式、归属表与固定过滤条件，禁止自行变更口径；如需按维度切分，仅可使用登记的可切分维度列）:\n${lines.join('\n')}\n\n`;
   108→}
