   110→// ---------- P2-14 统一指标查询（语义层查询接口，报表/看板/问数三端共享） ----------
   111→
   112→/** v0.9.21 指标直查金额单位（label 供响应标注，divisor>1 时才换算；与 liveQuery AMOUNT_UNIT_OPTIONS 同源） */
   113→export interface MetricAmountUnit {
   114→  label: string;
   115→  divisor: number;
   116→}
   117→
   118→/**
   119→ * 金额类指标关键词（与前端 src/utils/flexQueryBuilder.ts AMOUNT_COL_RE 保持一致，改动需双侧同步）：
   120→ * 指标名/口径说明/表达式任一命中即视为金额类指标
   121→ */
   122→const METRIC_AMOUNT_RE = /(金额|费用|收益|成本|利息|余额|收入|支出|价款|保费)/;
   123→
   124→/**
   125→ * 判定指标是否金额类且可换算：关键词命中且非 COUNT 类聚合（计数不随单位缩放，
   126→ * 与灵活查询 v0.5.4「COUNT/COUNT_DISTINCT 不换算」同规则）。
   127→ */
   128→export function isAmountMetric(metric: Pick<MetricDefinition, 'name' | 'description' | 'expr'>): boolean {
   129→  if (/^\s*COUNT\s*\(/i.test(metric.expr)) return false;
   130→  return METRIC_AMOUNT_RE.test(`${metric.name} ${metric.description} ${metric.expr}`);
   131→}
   132→
   133→/**
   134→ * 由指标定义生成「按维度切分」的查询 SQL（不执行，纯函数可单测）。
   135→ * 安全不变式：tableName/dimensions 均为 sanitize 校验过的合法标识符；请求维度必须在指标登记的
   136→ * dimensions 白名单内（调用方之外的维度一律拒绝）；filters 为治理审批过的固定片段。
   137→ * v0.9.21：amountUnit 非「元」且指标为金额类时，聚合结果按除数换算（ROUND(expr/divisor, 2)），
   138→ * 别名保持 value 不变（看板固化图表与重放依赖该别名）；unitApplied 标记是否实际换算。
   139→ */
   140→export function buildMetricQuerySql(
   141→  metric: MetricDefinition,
   142→  reqDims: string[],
   143→  limit = 100,
   144→  amountUnit?: MetricAmountUnit
   145→): { ok: true; sql: string; unitApplied: boolean } | { ok: false; error: string } {
   146→  if (metric.status !== 'ACTIVE') return { ok: false, error: '指标未生效，不可查询' };
   147→  const dims = Array.isArray(reqDims) ? reqDims : [];
   148→  for (const d of dims) {
   149→    if (!metric.dimensions.includes(d)) {
   150→      return { ok: false, error: `维度「${d}」不在指标「${metric.name}」的可切分维度白名单内` };
   151→    }
   152→  }
   153→  const safeLimit = Math.max(1, Math.min(1000, Math.floor(limit) || 100));
   154→  const dimSelect = dims.length > 0 ? `${dims.join(', ')}, ` : '';
   155→  const where = metric.filters ? ` WHERE ${metric.filters}` : '';
   156→  const groupBy = dims.length > 0 ? ` GROUP BY ${dims.join(', ')} ORDER BY \`value\` DESC` : '';
   157→  // 金额单位换算：divisor 来自固定白名单（1/1e4/1e6/1e8），纯数字拼接无注入风险
   158→  const unitApplied = !!amountUnit && amountUnit.divisor > 1 && isAmountMetric(metric);
   159→  const valueExpr = unitApplied ? `ROUND((${metric.expr})/${amountUnit!.divisor}, 2)` : metric.expr;
   160→  const sql = `SELECT ${dimSelect}${valueExpr} AS \`value\` FROM ${metric.tableName}${where}${groupBy} LIMIT ${safeLimit}`;
   161→  return { ok: true, sql, unitApplied };
   162→}
