   216→/** 写版本历史快照（创建/审批生效/变更/回滚均调用，变更留历史） */
   217→async function recordVersion(
   218→  metricId: number,
   219→  version: number,
   220→  snapshot: Omit<MetricDefinition, 'id' | 'version' | 'approvedBy' | 'approvedAt'>,
   221→  action: 'CREATE' | 'APPROVE' | 'UPDATE' | 'RESTORE',
   222→  actor: string
   223→): Promise<void> {
   224→  await getPool().query(
   225→    'INSERT INTO metric_versions (metric_id, version, snapshot_json, action, actor) VALUES (?, ?, ?, ?, ?)',
   226→    [metricId, version, JSON.stringify(snapshot), action, actor]
   227→  );
   228→}
