   287→
   288→/** 按 ID 取指标定义（P2-14 统一查询端点与治理流程共用） */
   289→export async function findMetricById(id: number): Promise<MetricDefinition | null> {
   290→  const [rows] = await getPool().query<RowDataPacket[]>('SELECT * FROM metric_definitions WHERE id = ? LIMIT 1', [id]);
   291→  return rows.length > 0 ? rowToMetric(rows[0]) : null;
   292→}
   293→
   294→/** ADMIN 审批通过：PENDING → ACTIVE，记录审批人与时间，版本快照入历史 */
   295→export async function approveMetric(id: number, actor: string): Promise<{ ok: true } | { ok: false; status: number; error: string }> {
   296→  const cur = await findMetricById(id);
   297→  if (!cur) return { ok: false, status: 404, error: '指标不存在' };
   298→  if (cur.status !== 'PENDING') return { ok: false, status: 400, error: '该指标不在待审批状态' };
   299→  await getPool().query(
   300→    "UPDATE metric_definitions SET status = 'ACTIVE', approved_by = ?, approved_at = NOW() WHERE id = ?",
   301→    [actor, id]
   302→  );
   303→  const snapshot = { ...cur, status: 'ACTIVE' as MetricStatus };
   304→  delete snapshot.id; delete snapshot.version; delete snapshot.approvedBy; delete snapshot.approvedAt;
   305→  await recordVersion(id, cur.version || 1, snapshot, 'APPROVE', actor);
   306→  return { ok: true };
   307→}
   308→
   309→/** ADMIN 驳回：PENDING → REJECTED（不进生产 linking，提议人可修改后重新提议） */
   310→export async function rejectMetric(id: number, actor: string): Promise<{ ok: true } | { ok: false; status: number; error: string }> {
   311→  const cur = await findMetricById(id);
   312→  if (!cur) return { ok: false, status: 404, error: '指标不存在' };
   313→  if (cur.status !== 'PENDING') return { ok: false, status: 400, error: '该指标不在待审批状态' };
   314→  await getPool().query("UPDATE metric_definitions SET status = 'REJECTED' WHERE id = ?", [id]);
   315→  return { ok: true };
   316→}
   317→
   318→/** 被驳回指标重新提议：REJECTED → PENDING（由提议人修改后再次进入审批） */
   319→export async function reproposeMetric(id: number, actor: string): Promise<{ ok: true } | { ok: false; status: number; error: string }> {
   320→  const cur = await findMetricById(id);
   321→  if (!cur) return { ok: false, status: 404, error: '指标不存在' };
   322→  if (cur.status !== 'REJECTED') return { ok: false, status: 400, error: '仅被驳回的指标可重新提议' };
   323→  await getPool().query("UPDATE metric_definitions SET status = 'PENDING' WHERE id = ?", [id]);
   324→  return { ok: true };
   325→}
