   354→/** 版本回溯：将指定版本快照应用回指标定义，version+1 并记 RESTORE 历史（历史本身不可变） */
   355→export async function restoreMetricVersion(id: number, version: number, actor: string): Promise<{ ok: true } | { ok: false; status: number; error: string }> {
   356→  const cur = await findMetricById(id);
   357→  if (!cur) return { ok: false, status: 404, error: '指标不存在' };
   358→  if (cur.status === 'PENDING') return { ok: false, status: 400, error: '待审批指标不可回溯' };
   359→  const [rows] = await getPool().query<RowDataPacket[]>(
   360→    'SELECT * FROM metric_versions WHERE metric_id = ? AND version = ? ORDER BY id DESC LIMIT 1',
   361→    [id, version]
   362→  );
   363→  if (rows.length === 0) return { ok: false, status: 404, error: '版本不存在' };
   364→  let snap: any;
   365→  try { snap = JSON.parse(String(rows[0].snapshot_json || '{}')); } catch { return { ok: false, status: 500, error: '版本快照损坏' }; }
   366→  const cleaned = sanitizeMetricInput({ ...snap, dataSourceId: cur.dataSourceId });
   367→  if (cleaned.ok !== true) return { ok: false, status: 500, error: `版本快照校验失败：${cleaned.error}` };
   368→  // 回溯后若原指标为 ACTIVE 则保持生效；DISABLED 保持停用
   369→  const status: MetricStatus = cur.status === 'ACTIVE' ? 'ACTIVE' : 'DISABLED';
   370→  const nextVersion = (cur.version || 1) + 1;
   371→  await getPool().query(
   372→    `UPDATE metric_definitions SET name = ?, aliases_json = ?, description = ?, expr = ?, table_name = ?, filters = ?, dimensions_json = ?, status = ?, version = ? WHERE id = ?`,
   373→    [cleaned.metric.name, JSON.stringify(cleaned.metric.aliases), cleaned.metric.description, cleaned.metric.expr, cleaned.metric.tableName, cleaned.metric.filters, JSON.stringify(cleaned.metric.dimensions || []), status, nextVersion, id]
   374→  );
   375→  await recordVersion(id, nextVersion, { ...cleaned.metric, status }, 'RESTORE', actor);
   376→  return { ok: true };
   377→}
