   405→/** 组装指标库导出文件（纯函数可单测） */
   406→export function buildMetricsExport(
   407→  dataSourceId: string,
   408→  dataSourceName: string,
   409→  metrics: MetricDefinition[],
   410→  exportedBy: string
   411→): MetricsExportFile {
   412→  return {
   413→    version: '1.0',
   414→    type: 'metric-definitions',
   415→    exportedAt: new Date().toISOString(),
   416→    exportedBy,
   417→    dataSourceId,
   418→    dataSourceName,
   419→    metricCount: metrics.length,
   420→    metrics: metrics.map((m) => ({
   421→      name: m.name,
   422→      aliases: m.aliases,
   423→      description: m.description,
   424→      expr: m.expr,
   425→      tableName: m.tableName,
   426→      filters: m.filters,
   427→      dimensions: m.dimensions,
   428→      status: m.status,
   429→    })),
   430→  };
   431→}
   432→
   433→/** 指标导入冲突处理策略：同名指标跳过 / 覆盖更新（指标名在数据源内唯一，不支持 append 重复新增） */
   434→export type MetricMergeStrategy = 'skip' | 'overwrite';
   435→
   436→export interface MetricImportResult {
   437→  success: boolean;
   438→  dryRun: boolean;
   439→  mergeStrategy: MetricMergeStrategy;
   440→  importedCount: number;
   441→  updatedCount: number;
   442→  skippedCount: number;
   443→  errorCount: number;
   444→  errors: Array<{ name: string; message: string }>;
   445→  summary: { totalItems: number; newItems: number; conflictItems: number; invalidItems: number };
   446→}
   447→
   448→/** 单次导入文件条目上限（防滥用；指标库治理量级远小于此） */
   449→const MAX_IMPORT_ITEMS = 500;
   450→
   451→/**
   452→ * 从导出文件恢复指标定义到指定数据源（仅 ADMIN 经路由调用）。
   453→ * - 每条经 sanitizeMetricInput 校验（与手工创建同一安全口径；PENDING/REJECTED 状态归一为 ACTIVE，
   454→ *   因导入即管理员直接生效，不绕过治理状态机）；
   455→ * - 冲突判定：目标数据源下同指标名；skip 跳过，overwrite 经 updateMetric 覆盖（版本 +1 留历史）；
   456→ * - 新增经 createMetric autoApprove 直接生效（version=1 写 CREATE 快照）；
   457→ * - 文件内部同名：首条处理后记入冲突集合，后续按冲突策略处理（与知识库导入语义一致）；
   458→ * - dryRun 仅统计不写库。
   459→ */
   460→export async function importMetrics(
   461→  dataSourceId: string,
   462→  items: unknown[],
   463→  strategy: MetricMergeStrategy,
   464→  dryRun: boolean,
   465→  actor: string
   466→): Promise<MetricImportResult> {
   467→  const result: MetricImportResult = {
   468→    success: true,
   469→    dryRun,
   470→    mergeStrategy: strategy,
   471→    importedCount: 0,
   472→    updatedCount: 0,
   473→    skippedCount: 0,
   474→    errorCount: 0,
   475→    errors: [],
   476→    summary: { totalItems: items.length, newItems: 0, conflictItems: 0, invalidItems: 0 },
   477→  };
   478→
   479→  // 冲突判定依据：目标数据源现有 指标名 → id 映射
   480→  const [rows] = await getPool().query<RowDataPacket[]>(
   481→    'SELECT id, name FROM metric_definitions WHERE data_source_id = ?',
   482→    [dataSourceId]
   483→  );
   484→  const existingByName = new Map<string, number>(rows.map((r: any) => [String(r.name), Number(r.id)]));
   485→
   486→  for (const raw of items.slice(0, MAX_IMPORT_ITEMS)) {
   487→    const name = typeof (raw as any)?.name === 'string' ? String((raw as any).name).trim() : '';
   488→    const cleaned = sanitizeMetricInput({ ...(raw as object), dataSourceId });
   489→    if (cleaned.ok !== true) {
   490→      result.summary.invalidItems++;
   491→      result.errorCount++;
   492→      result.errors.push({ name: name || '(未命名)', message: cleaned.error });
   493→      continue;
   494→    }
   495→    const conflictId = existingByName.get(cleaned.metric.name);
   496→    try {
   497→      if (conflictId !== undefined) {
   498→        result.summary.conflictItems++;
   499→        if (strategy === 'skip') {
   500→          result.skippedCount++;
   501→          continue;
   502→        }
   503→        // overwrite：覆盖更新（版本 +1 留历史；PENDING 指标被 updateMetric 拒绝时记错误）
   504→        if (!dryRun) {
   505→          const { dataSourceId: _ignored, ...rest } = cleaned.metric;
   506→          const r = await updateMetric(conflictId, rest, actor);
   507→          if (r.ok !== true) throw new Error(r.error);
   508→        }
   509→        result.updatedCount++;
   510→        continue;
   511→      }
   512→      result.summary.newItems++;
   513→      if (!dryRun) {
   514→        const r = await createMetric(cleaned.metric, actor, { autoApprove: true });
   515→        if (r.ok !== true) throw new Error(r.error);
   516→        // 文件内部同名：首条入库后记入冲突集合，后续同名条目按冲突策略处理（overwrite 可命中更新）
   517→        existingByName.set(cleaned.metric.name, r.id);
   518→      } else {
   519→        existingByName.set(cleaned.metric.name, -1);
   520→      }
   521→      result.importedCount++;
   522→    } catch (err: any) {
   523→      result.errorCount++;
   524→      result.errors.push({ name: cleaned.metric.name, message: err?.message || '未知错误' });
   525→    }
   526→  }
   527→
   528→  result.success = result.errorCount === 0;
   529→  return result;
   530→}
