     1→/**
     2→ * P1-5 时序预测统计引擎（纯函数，无 IO 依赖）：
     3→ * 三档统计模型——移动平均（含漂移修正）/ 最小二乘线性回归 / 加法季节分解，
     4→ * auto 模式通过尾部回测（留出法）按 MAPE 择优，输出点预测 + 波动区间 + 中文诊断。
     5→ * 说明：不做数据插值/补点，调用方负责按时间顺序传入数值序列。
     6→ */
     7→
     8→export type ForecastModel = 'auto' | 'ma' | 'lr' | 'seasonal';
     9→export type ResolvedModel = Exclude<ForecastModel, 'auto'>;
    10→
    11→export interface ForecastPoint {
    12→  /** 距历史终点的步长（1 = 下一期） */
    13→  step: number;
    14→  yhat: number;
    15→  /** 区间下界（默认 80% 置信） */
    16→  lower: number;
    17→  /** 区间上界（默认 80% 置信） */
    18→  upper: number;
    19→}
    20→
    21→export interface ForecastFit {
    22→  /** 平均绝对百分比误差（%，真值含 0 时跳过该点；全部无效则为 null） */
    23→  mape: number | null;
    24→  /** 拟合优度 R²（序列恒定等退化情形为 null） */
    25→  r2: number | null;
    26→  rmse: number;
    27→}
    28→
    29→export interface ForecastResult {
    30→  model: ResolvedModel;
    31→  points: ForecastPoint[];
    32→  fit: ForecastFit;
    33→  /** 各候选模型回测 MAPE（auto 模式择优依据，供前端展示） */
    34→  backtest: { model: ResolvedModel; mape: number | null }[];
    35→  /** 中文诊断说明（样本量/趋势/季节/拟合质量） */
    36→  diagnostics: string[];
    37→}
    38→
    39→export interface ForecastOptions {
    40→  /** 预测期数（1~24） */
    41→  periods: number;
    42→  model?: ForecastModel;
    43→  /** 季节周期（seasonal 模型必填；auto 回测候选由内部生成） */
    44→  seasonalPeriod?: number;
    45→  /** 区间 z 值，默认 1.28（约 80%） */
    46→  intervalZ?: number;
    47→}
    48→
    49→export const MIN_SERIES_LENGTH = 3;
    50→export const MAX_FORECAST_PERIODS = 24;
    51→const MA_WINDOW_MAX = 3;
    52→
    53→interface FittedModel {
    54→  name: ResolvedModel;
    55→  /** 全样本拟合值（长度 = 输入长度；拟合不可得的头部位置用原值占位） */
    56→  fitted: number[];
    57→  /** 预测未来第 h 期（h 从 1 开始） */
    58→  predict: (h: number) => number;
    59→  /** 趋势斜率（每期变化量，用于诊断） */
    60→  slope: number;
    61→  seasonPeriod?: number;
    62→}
    63→
    64→/** 入口：输入历史数值序列，输出预测点与诊断；序列非法或过短抛错（调用方应先行校验并转 400） */
    65→export function forecastSeries(values: number[], opts: ForecastOptions): ForecastResult {
    66→  if (!Array.isArray(values) || values.length < MIN_SERIES_LENGTH) {
    67→    throw new Error(`至少需要 ${MIN_SERIES_LENGTH} 个历史数据点`);
    68→  }
    69→  const series = values.map((v) => Number(v));
    70→  if (series.some((v) => !Number.isFinite(v))) {
    71→    throw new Error('历史序列包含非数值项');
    72→  }
    73→  const periods = Math.floor(opts.periods);
    74→  if (!Number.isFinite(periods) || periods < 1 || periods > MAX_FORECAST_PERIODS) {
    75→    throw new Error(`预测期数需为 1~${MAX_FORECAST_PERIODS} 的整数`);
    76→  }
    77→  const z = Number.isFinite(opts.intervalZ) && (opts.intervalZ as number) > 0 ? (opts.intervalZ as number) : 1.28;
    78→
    79→  const requested = opts.model || 'auto';
    80→  const { chosen, backtest } = requested === 'auto'
    81→    ? pickByBacktest(series)
    82→    : { chosen: fitResolved(series, requested, opts.seasonalPeriod), backtest: [] };
    83→
    84→  const diagnostics = describe(series, chosen, chosen.name === 'seasonal' ? chosen.seasonPeriod : undefined);
    85→
    86→  const fit = evaluateFit(series, chosen.fitted);
    87→  // 波动区间：残差标准差 × z × sqrt(step)（步长越大不确定性越高）
    88→  const residualStd = fit.rmse;
    89→
    90→  const points: ForecastPoint[] = [];
    91→  for (let h = 1; h <= periods; h++) {
    92→    const yhat = chosen.predict(h);
    93→    const band = z * residualStd * Math.sqrt(h);
    94→    points.push({
    95→      step: h,
    96→      yhat: round4(yhat),
    97→      lower: round4(yhat - band),
    98→      upper: round4(yhat + band),
    99→    });
   100→  }
   101→  return { model: chosen.name, points, fit, backtest, diagnostics };
   102→}
   103→
   104→/** 指定模型拟合（模型名已解析，非 auto） */
   105→function fitResolved(series: number[], model: ResolvedModel, seasonalPeriod?: number): FittedModel {
   106→  if (model === 'seasonal') {
   107→    const p = Number.isFinite(seasonalPeriod) && (seasonalPeriod as number) >= 2 ? Math.floor(seasonalPeriod as number) : 0;
   108→    if (p < 2 || series.length < 2 * p) {
   109→      throw new Error(`季节模型需要至少 ${2 * (p || 2)} 个数据点与合法周期（当前周期 ${p || '未指定'}）`);
   110→    }
