   210→      if (j < 0 || j >= n) continue;
   211→      sum += series[j];
   212→      cnt++;
   213→    }
   214→    trend[i] = cnt > 0 ? sum / cnt : null;
   215→  }
   216→  // 季节增量：按相位聚合去趋势偏差
   217→  const seasonalSum = new Array(p).fill(0);
   218→  const seasonalCnt = new Array(p).fill(0);
   219→  for (let i = 0; i < n; i++) {
   220→    if (trend[i] === null) continue;
   221→    const phase = i % p;
   222→    seasonalSum[phase] += series[i] - (trend[i] as number);
   223→    seasonalCnt[phase]++;
   224→  }
   225→  const seasonal = seasonalSum.map((s, i) => (seasonalCnt[i] > 0 ? s / seasonalCnt[i] : 0));
   226→  const seasonMean = seasonal.reduce((a, b) => a + b, 0) / p;
   227→  for (let i = 0; i < p; i++) seasonal[i] -= seasonMean;
   228→  // 趋势：对可得趋势点做线性回归（x 为原始位置 1-based）
   229→  const idx: number[] = [];
   230→  for (let i = 0; i < n; i++) if (trend[i] !== null) idx.push(i);
   231→  const xs = idx.map((i) => i + 1);
