   237→    predict: (h) => a + b * (n + h) + seasonal[(n + h - 1) % p],
   238→    slope: b,
   239→    seasonPeriod: p,
   240→  };
   241→}
   242→
   243→function ols(xs: number[], ys: number[]): { a: number; b: number } {
   244→  const n = xs.length;
   245→  if (n === 0) return { a: 0, b: 0 };
   246→  const meanX = xs.reduce((a, b) => a + b, 0) / n;
   247→  const meanY = ys.reduce((a, b) => a + b, 0) / n;
   248→  let sxy = 0;
   249→  let sxx = 0;
   250→  for (let i = 0; i < n; i++) {
   251→    const dx = xs[i] - meanX;
   252→    sxy += dx * (ys[i] - meanY);
   253→    sxx += dx * dx;
   254→  }
   255→  const b = sxx === 0 ? 0 : sxy / sxx;
   256→  return { a: meanY - b * meanX, b };
   257→}
