   259→// ---------- 评估与诊断 ----------
   260→
   261→/** in-sample 拟合评估：MAPE / RMSE / R² */
   262→export function evaluateFit(series: number[], fitted: number[]): ForecastFit {
   263→  const n = series.length;
   264→  let sse = 0;
   265→  let mapeSum = 0;
   266→  let mapeCnt = 0;
   267→  for (let i = 0; i < n; i++) {
   268→    const diff = series[i] - fitted[i];
   269→    sse += diff * diff;
   270→    if (Math.abs(series[i]) > 1e-9) {
   271→      mapeSum += Math.abs(diff / series[i]);
   272→      mapeCnt++;
   273→    }
   274→  }
   275→  const mean = series.reduce((a, b) => a + b, 0) / n;
   276→  let sst = 0;
   277→  for (let i = 0; i < n; i++) sst += (series[i] - mean) ** 2;
   278→  return {
   279→    mape: mapeCnt > 0 ? round2((mapeSum / mapeCnt) * 100) : null,
   280→    r2: sst > 1e-12 ? round4(1 - sse / sst) : null,
   281→    rmse: round4(Math.sqrt(sse / n)),
   282→  };
   283→}
   284→
   285→function mapeOf(actual: number[], predicted: number[]): number | null {
   286→  let sum = 0;
   287→  let cnt = 0;
   288→  for (let i = 0; i < actual.length; i++) {
   289→    if (Math.abs(actual[i]) > 1e-9) {
   290→      sum += Math.abs((actual[i] - predicted[i]) / actual[i]);
   291→      cnt++;
   292→    }
   293→  }
   294→  return cnt > 0 ? (sum / cnt) * 100 : null;
   295→}
