   300→  seasonal: '季节分解（趋势 + 周期）',
   301→};
   302→
   303→function describe(series: number[], model: FittedModel, seasonPeriod?: number): string[] {
   304→  const out: string[] = [];
   305→  out.push(`基于 ${series.length} 期历史，采用${MODEL_LABELS[model.name]}模型`);
   306→  const mean = series.reduce((a, b) => a + b, 0) / series.length;
   307→  const relSlope = Math.abs(mean) > 1e-9 ? (model.slope / mean) * 100 : 0;
   308→  if (Math.abs(relSlope) < 1) out.push('整体呈平稳走势（每期变化不足均值的 1%，趋势信号弱）');
   309→  else out.push(`整体呈${model.slope > 0 ? '上升' : '下降'}趋势（每期约 ${model.slope > 0 ? '+' : ''}${round4(model.slope)}，约占均值 ${Math.abs(relSlope).toFixed(1)}%）`);
