   169→  for (const r of rows) {
   170→    if (!r || typeof r !== 'object') continue;
   171→    const dimVal = dimKey ? String((r as Record<string, unknown>)[dimKey] ?? '') : '合计';
   172→    const periodVal = String((r as Record<string, unknown>)[periodKey]);
   173→    const metricVal = Number((r as Record<string, unknown>)[metricKey]);
   174→    if (!dimVal || !Number.isFinite(metricVal)) continue;
   175→    if (periodVal !== currentPeriod && periodVal !== previousPeriod) continue;
   176→    const entry = grouped.get(dimVal) ?? { current: 0, previous: 0 };
   177→    if (periodVal === currentPeriod) entry.current += metricVal;
   178→    else entry.previous += metricVal;
   179→    grouped.set(dimVal, entry);
   180→  }
   181→  if (grouped.size === 0) return { ok: false, reason: '最新两期无可聚合数据' };
   182→
   183→  return {
   184→    ok: true,
   185→    periods: [previousPeriod, currentPeriod],
   186→    rows: Array.from(grouped.entries()).map(([dim, v]) => ({ dims: [dim], current: v.current, previous: v.previous })),
   187→  };
   188→}
