    92→
    93→/** 调用 LLM 生成推演计划；首轮未过校验时纠偏重试一次，仍失败抛错由路由转 422 */
    94→export async function generateWhatIfPlan(input: {
    95→  baseSql: string;
    96→  scenario: string;
    97→  schema: any[];
    98→  question?: string;
    99→}): Promise<WhatIfPlan> {
   100→  const { baseSql, scenario, schema } = input;
   101→  const system = buildWhatIfSystem(schema);
   102→  const user = `【原始 SQL】\n${baseSql}\n\n${input.question ? `【原始提问背景】\n${input.question}\n\n` : ''}【希望模拟的场景】\n${scenario}`;
   103→
   104→  const text = await callLLMJson(system, user);
   105→  const plan = parseWhatIfPlan(text, baseSql);
   106→  if (plan) return plan;
   107→
   108→  logger.error('[WhatIf] invalid plan structure, raw output head:', text.slice(0, 300));
   109→  const retryText = await callLLMJson(system, user, [
   110→    { role: 'assistant', content: text.slice(0, 2000) },
   111→    {
   112→      role: 'user',
   113→      content:
   114→        '上一次输出不符合契约。请重新只输出一个纯 JSON 对象：scenarioSql（基于原始 SQL 改写的单条 SELECT，必须与原 SQL 有实质条件差异，表名列名沿用原文）、explanation（非空中文说明改了什么）、parameterChanges（数组，可为空数组）。不要 markdown 标记与任何额外文字。',
   115→    },
   116→  ]);
   117→  const retryPlan = parseWhatIfPlan(retryText, baseSql);
   118→  if (!retryPlan) {
   119→    logger.error('[WhatIf] retry invalid, raw output head:', retryText.slice(0, 300));
   120→    throw new Error('情景改写结果未通过结构校验');
   121→  }
   122→  return retryPlan;
   123→}
   124→
   125→// ---------- 结果对比 ----------
   126→
   127→export interface NumericPair {
   128→  sum: number;
   129→  avg: number;
   130→}
   131→
   132→export interface WhatIfComparison {
   133→  column: string;
   134→  before: NumericPair;
   135→  after: NumericPair;
   136→  delta: NumericPair;
   137→  /** 相对变化率（%，before 为 0 时 null） */
   138→  deltaPct: { sum: number | null; avg: number | null };
   139→}
   140→
   141→export const MAX_COMPARE_COLUMNS = 12;
   142→
   143→/**
   144→ * 对比两组结果行的数值列：对每列计算 sum/avg 的 before→after 变化。
   145→ * 仅保留两组都至少含一个数值的列（文本列自动跳过）；列序按 before 首行顺序。
   146→ */
   147→export function compareOutcomes(
   148→  beforeRows: Record<string, unknown>[],
   149→  afterRows: Record<string, unknown>[],
   150→  opts?: { maxColumns?: number },
   151→): WhatIfComparison[] {
   152→  const maxColumns = Number.isFinite(opts?.maxColumns) && (opts?.maxColumns as number) > 0
   153→    ? Math.floor(opts?.maxColumns as number)
   154→    : MAX_COMPARE_COLUMNS;
   155→  if (!Array.isArray(beforeRows) || !Array.isArray(afterRows) || beforeRows.length === 0 || afterRows.length === 0) {
   156→    return [];
   157→  }
   158→
   159→  const columns: string[] = [];
   160→  for (const row of beforeRows) {
   161→    if (!row || typeof row !== 'object') continue;
   162→    for (const key of Object.keys(row)) {
   163→      if (!columns.includes(key)) columns.push(key);
   164→    }
   165→  }
   166→
   167→  const out: WhatIfComparison[] = [];
   168→  for (const column of columns) {
   169→    if (out.length >= maxColumns) break;
   170→    const beforeNums = numericValues(beforeRows, column);
   171→    const afterNums = numericValues(afterRows, column);
   172→    if (beforeNums.length === 0 || afterNums.length === 0) continue;
   173→
   174→    const before: NumericPair = { sum: round4(sum(beforeNums)), avg: round4(avg(beforeNums)) };
   175→    const after: NumericPair = { sum: round4(sum(afterNums)), avg: round4(avg(afterNums)) };
   176→    out.push({
   177→      column,
   178→      before,
   179→      after,
   180→      delta: { sum: round4(after.sum - before.sum), avg: round4(after.avg - before.avg) },
   181→      deltaPct: {
   182→        sum: Math.abs(before.sum) > 1e-9 ? round2(((after.sum - before.sum) / Math.abs(before.sum)) * 100) : null,
   183→        avg: Math.abs(before.avg) > 1e-9 ? round2(((after.avg - before.avg) / Math.abs(before.avg)) * 100) : null,
   184→      },
   185→    });
   186→  }
   187→  return out;
   188→}
   189→
   190→function numericValues(rows: Record<string, unknown>[], column: string): number[] {
   191→  const out: number[] = [];
   192→  for (const row of rows) {
   193→    if (!row || typeof row !== 'object') continue;
   194→    const v = (row as Record<string, unknown>)[column];
   195→    if (v === null || v === undefined || v === '') continue;
   196→    const n = typeof v === 'number' ? v : Number(v);
   197→    if (Number.isFinite(n)) out.push(n);
   198→  }
   199→  return out;
   200→}
   201→
   202→/** 对比表 → 中文摘要（供 LLM 解读引用与前端直接展示） */
   203→export function summarizeComparison(comparisons: WhatIfComparison[]): string[] {
   204→  if (comparisons.length === 0) return ['（无可对比的数值列）'];
   205→  return comparisons.map((c) => {
   206→    const sign = (v: number) => (v > 0 ? '+' : '');
   207→    const pct = (v: number | null) => (v === null ? '（基准为 0，变化率不适用）' : `${sign(v)}${v}%`);
   208→    if (Math.abs(c.delta.sum) < 1e-9 && Math.abs(c.delta.avg) < 1e-9) {
   209→      return `- ${c.column}：无变化（${c.before.sum}）`;
   210→    }
   211→    // 行数不变时两口径一致，合并展示避免冗余
   212→    if (c.deltaPct.sum !== null && c.deltaPct.sum === c.deltaPct.avg) {
   213→      return `- ${c.column}：${c.before.sum} → ${c.after.sum}（${sign(c.delta.sum)}${c.delta.sum}，${pct(c.deltaPct.sum)}）`;
   214→    }
   215→    return `- ${c.column}：合计 ${c.before.sum} → ${c.after.sum}（${pct(c.deltaPct.sum)}）；均值 ${c.before.avg} → ${c.after.avg}（${pct(c.deltaPct.avg)}）`;
   216→  });
   217→}
   218→
   219→function sum(nums: number[]): number {
   220→  return nums.reduce((a, b) => a + b, 0);
   221→}
   222→
   223→function avg(nums: number[]): number {
   224→  return nums.length === 0 ? 0 : sum(nums) / nums.length;
   225→}
   226→
   227→function round2(v: number): number {
   228→  return Math.round(v * 100) / 100;
   229→}
   230→
   231→function round4(v: number): number {
   232→  return Math.round(v * 10000) / 10000;
   233→}
   234→

