     3→ * 供查询、报表等端点共享；双阶段（SQL 生成 / 数据分析）均通过 callLLMJson 调用。
     4→ * 引擎选择优先级：请求级覆盖（setLlmOverride，用户自选模型）>
     5→ * 阶段级路由（callLLMJson opts.route，如 SQL 生成快速模型 P1-2）>
     6→ * AI_ENGINE 显式指定（ollama/gemini/qwen/deepseek）> 按密钥存在性自动（gemini/qwen/deepseek）> ollama。
     7→ */
     8→import { AsyncLocalStorage } from 'async_hooks';
     9→import { recordLlmUsage } from './llmUsage';
    10→import {
    11→  getOllamaBackendStates,
    12→  isAbortErr,
    13→  ollamaTimeoutMs,
    14→  ollamaUrl,
    15→  pickOllamaBackend,
    16→  withOllamaBackend,
    17→} from './ollamaBackends';
    18→import {
    19→  CircuitBreaker,
    20→  LatencyWindow,
    21→  Semaphore,
    22→  adaptiveTimeoutMs,
    23→  makeLlmError,
    24→  withRetry,
    25→} from './llmResilience';
    26→import { logger } from '../infra/logger';
    27→
    28→export interface ChatMessage {
    29→  role: 'system' | 'user' | 'assistant';
    30→  content: string;
    31→}
    32→
    33→// 惰性读取环境变量（ESM import 提升会使模块级读取早于 dotenv.config()，同 auth.ts/db.ts 先例）
    34→export const llmModel = () => overrideModel('ollama') || process.env.LLM_MODEL || 'deepseek-r1:32b';
    35→
    36→/** P0-2：各引擎响应的最小结构类型（仅声明取用字段，非法载荷由既有运行时校验兑底） */
    37→interface OllamaTagsResponse {
    38→  models?: Array<{ name?: string }>;
    39→}
    40→/** OpenAI 兼容 chat 响应（Qwen 百炼 / Coding Plan） */
    41→interface OpenAiChatResponse {
    42→  choices?: Array<{ message?: { content?: string } }>;
    43→  usage?: { prompt_tokens?: number; completion_tokens?: number };
    44→}
    45→/** Ollama /api/chat 响应 */
    46→interface OllamaChatResponse {
    47→  message?: { content?: string };
    48→  prompt_eval_count?: number;
    49→  eval_count?: number;
    50→}
    51→// 通义千问（百炼 OpenAI 兼容协议）；Coding Plan（sk-sp-）需将 QWEN_URL 指向
    52→// https://coding.dashscope.aliyuncs.com/v1，普通按量 Key 用默认端点即可
    53→export const qwenUrl = () => process.env.QWEN_URL || 'https://dashscope.aliyuncs.com/compatible-mode/v1';
    54→export const qwenModel = () => overrideModel('qwen') || process.env.QWEN_MODEL || 'qwen3.8-max';
    55→export const qwenTimeoutMs = () => Number(process.env.QWEN_TIMEOUT_MS) || 180_000;
    56→// DeepSeek 官方 API（OpenAI 兼容协议）；deepseek-flash 为 V4.1 Flash 的 API 模型名
    57→export const deepseekUrl = () => process.env.DEEPSEEK_URL || 'https://api.deepseek.com/v1';
    58→export const deepseekModel = () => overrideModel('deepseek') || process.env.DEEPSEEK_MODEL || 'deepseek-flash';
    59→export const deepseekTimeoutMs = () => Number(process.env.DEEPSEEK_TIMEOUT_MS) || 180_000;
    60→const GEMINI_MODEL = 'gemini-3.6-flash';
    61→export const geminiModel = () => overrideModel('gemini') || GEMINI_MODEL;
