     1→/**
     2→ * L6 审计层：智能问数全链路审计日志。
     3→ * 成功、降级、错误与被拒绝（输入/权限/频率/开关）的请求全部落账，
     4→ * 写入失败仅告警不阻塞主流程（审计不应成为可用性瓶颈）。
     5→ */
     6→import { getPool } from './db';
     7→import { observeAudit } from './monitoring';
     8→import { logger } from './logger';
     9→
    10→export type AuditStatus =
    11→  | 'SUCCESS'
    12→  | 'CACHE'
    13→  | 'FALLBACK'
    14→  | 'ERROR'
    15→  | 'CLARIFY'
    16→  | 'REFUSED'
    17→  // v0.9.2 长任务队列（改进计划 2-1）：异步任务入队留痕，终态由 worker 侧另行落账
    18→  | 'QUEUED'
    19→  | 'DENIED_INPUT'
    20→  | 'DENIED_AUTH'
    21→  | 'DENIED_RATE'
    22→  | 'DENIED_SWITCH';
    23→
    24→export interface AuditEntry {
    25→  userId: number;
    26→  username: string;
    27→  endpoint: 'query' | 'report' | 'query_report' | 'saved_report' | 'report_template' | 'export' | 'dashboard_widget' | 'flex_query' | 'patrol' | 'analytics' | 'agent' | 'admin';
    28→  dataSourceId?: string;
    29→  question?: string;
    30→  status: AuditStatus;
    31→  detail?: string;
    32→  /** 真实执行的 SQL（P0 双阶段模式）；-1 行数表示未执行 */
    33→  executedSql?: string;
    34→  rowCount?: number;
    35→  durationMs?: number;
    36→}
    37→
    38→export function writeAudit(entry: AuditEntry): void {
    39→  observeAudit(entry); // Prometheus 旁路埋点（fail-open，不影响审计落库）
    40→  getPool()
    41→    .query(
    42→      `INSERT INTO query_audit_log
    43→        (user_id, username, endpoint, data_source_id, question, status, detail, executed_sql, row_count, duration_ms)
    44→       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    45→      [
    46→        entry.userId,
    47→        entry.username,
    48→        entry.endpoint,
    49→        (entry.dataSourceId || '').slice(0, 64),
    50→        (entry.question || '').slice(0, 500),
    51→        entry.status,
    52→        (entry.detail || '').slice(0, 255),
    53→        (entry.executedSql || '').slice(0, 2000),
    54→        entry.rowCount === undefined ? -1 : Math.round(entry.rowCount),
    55→        Math.max(0, Math.round(entry.durationMs || 0)),
    56→      ]
    57→    )
    58→    .catch((err) => {
    59→      logger.warn('[Audit] 审计日志写入失败:', err?.message || err);
    60→    });
    61→}
