    28→  {
    29→    key: 'phone',
    30→    label: '手机号',
    31→    columnPattern: /phone|mobile|tel(?:ephone)?|sjh|shouji/i,
    32→    valuePattern: /(?<!\d)1[3-9]\d{9}(?!\d)/,
    33→    mask: (v) => (v.length >= 7 ? `${v.slice(0, 3)}****${v.slice(-4)}` : '****'),
    34→  },
