   101→ * ADMIN（豁免开启时）/全局关闭/空集 直接原样返回。
   102→ */
   103→export function maskRows(rows: Record<string, any>[], user: Pick<AuthUser, 'role'>): MaskedRows {
   104→  if (!isDlpEnabled() || isDlpExempt(user) || !Array.isArray(rows) || rows.length === 0) {
   105→    return { rows, maskedColumns: [], maskedLabels: [] };
   106→  }
   107→
   108→  const columns = Object.keys(rows[0] || {});
   109→  // 列规则映射：列名命中优先；否则抽样内容判定
   110→  const colRule = new Map<string, DlpRule>();
   111→  const sample = rows.slice(0, SAMPLE_ROWS);
   112→  for (const col of columns) {
   113→    const named = ruleForColumn(col);
   114→    if (named) {
   115→      colRule.set(col, named);
   116→      continue;
   117→    }
   118→    for (const row of sample) {
   119→      const hit = ruleForValue(row[col]);
   120→      if (hit) {
   121→        colRule.set(col, hit);
   122→        break;
   123→      }
   124→    }
   125→  }
   126→
   127→  if (colRule.size === 0) return { rows, maskedColumns: [], maskedLabels: [] };
   128→
   129→  const masked = rows.map((row) => {
   130→    const next: Record<string, any> = { ...row };
   131→    for (const [col, rule] of colRule) {
   132→      const v = next[col];
   133→      if (v === null || v === undefined || v === '') continue;
   134→      next[col] = rule.mask(String(v));
   135→    }
   136→    return next;
   137→  });
   138→
   139→  const maskedColumns = [...colRule.keys()];
   140→  const maskedLabels = [...new Set([...colRule.values()].map((r) => r.label))];
   141→  return { rows: masked, maskedColumns, maskedLabels };
   142→}
   143→
   144→/**
   145→ * 问数结果 payload 脱敏：处理 payload.result.rows（存在时），返回新 payload
   146→ * （result 对象同样拷贝，避免污染缓存中的原始引用），并附加 dlp 标记供前端提示。
   147→ */
   148→export function maskQueryPayload<T extends { result?: { rows?: Record<string, any>[] } }>(
   149→  payload: T,
   150→  user: Pick<AuthUser, 'role'>,
   151→): T & { dlp?: { maskedColumns: string[]; maskedLabels: string[] } } {
   152→  const rows = payload?.result?.rows;
   153→  if (!Array.isArray(rows) || rows.length === 0) return payload;
   154→  const { rows: masked, maskedColumns, maskedLabels } = maskRows(rows, user);
   155→  if (maskedColumns.length === 0) return payload;
   156→  return {
   157→    ...payload,
   158→    result: { ...payload.result!, rows: masked },
   159→    dlp: { maskedColumns, maskedLabels },
   160→  };
   161→}
